/**
 * report.js — 명식 데이터를 서사형 리포트로 조합한다.
 *
 *   buildLifeReport(saju)        평생사주 (오행을 십신으로 대입해 구체적으로 풀이)
 *   buildYearReport(saju, year)  연도별 운세 (전체·금전·연애·행복·명리·직업·문서 + 월별)
 *
 * 문장은 전부 사람이 쓴 조각이고 엔진은 명식에 맞는 조각을 고르고 이어 붙인다.
 */

/* ═══ 조사 처리 ═════════════════════════════════════ */
function hasJong(w) {
  const c = String(w).charCodeAt(String(w).length - 1);
  if (c < 0xAC00 || c > 0xD7A3) return false;
  return (c - 0xAC00) % 28 !== 0;
}
const EUN = (w) => w + (hasJong(w) ? "은" : "는");   // 은/는
const IGA = (w) => w + (hasJong(w) ? "이" : "가");   // 이/가
const EUL = (w) => w + (hasJong(w) ? "을" : "를");   // 을/를
const IRA = (w) => w + (hasJong(w) ? "이라" : "라"); // 이라/라

/* 직업명처럼 괄호·기호로 끝나는 말 — 마지막 한글 음절로 받침을 따진다 */
function tailJong(w) {
  const m = String(w).match(/[가-힣](?![\s\S]*[가-힣])/);
  if (!m) return false;
  return (m[0].charCodeAt(0) - 0xAC00) % 28 !== 0;
}
const LEUN = (w) => w + (tailJong(w) ? "은" : "는");
const LIGA = (w) => w + (tailJong(w) ? "이" : "가");
const LRO  = (w) => w + (tailJong(w) ? "으로" : "로");

/* ═══ 오행 관계 ═══════════════════════════════════════ */
const EL_ORDER = ["목","화","토","금","수"];
const GEN    = { 목:"화", 화:"토", 토:"금", 금:"수", 수:"목" };  // 내가 생하는
const CTL    = { 목:"토", 화:"금", 토:"수", 금:"목", 수:"화" };  // 내가 극하는
const GEN_BY = { 목:"수", 화:"목", 토:"화", 금:"토", 수:"금" };  // 나를 생하는
const CTL_BY = { 목:"금", 화:"수", 토:"목", 금:"화", 수:"토" };  // 나를 극하는

/** 일간 오행 기준으로 다섯 오행이 각각 어떤 십신 자리인지 */
function elementRoles(me) {
  return {
    [me]:         "비겁",
    [GEN[me]]:    "식상",
    [CTL[me]]:    "재성",
    [CTL_BY[me]]: "관성",
    [GEN_BY[me]]: "인성",
  };
}

