/* ═══ 나이 계산 ═════════════════════════════════════ */
/** 생일까지 반영한 만 나이 (소수점 포함). ref 미지정 시 오늘 기준 */
export function exactAge(saju, ref) {
  const b = new Date(saju.solar.year, saju.solar.month - 1, saju.solar.day,
                     saju.solar.hour || 0, saju.solar.minute || 0);
  const r = ref instanceof Date ? ref : new Date();
  return (r - b) / (365.2425 * 86400000);
}
/** 특정 연도의 생일 시점 만 나이 (연운용) */
export function ageInYear(saju, year) {
  return year - saju.solar.year;
}
/** 만 나이 정수 */
export function koreanAge(saju, ref) {
  return Math.floor(exactAge(saju, ref));
}

