// 출처 간 표기가 갈리는 칸. 감수 때 확정할 것.
const JOHU_UNCERTAIN = { "병-묘":"보조용신이 己인지 甲인지 출처가 갈림" };

const CN2KO = { 甲:"갑",乙:"을",丙:"병",丁:"정",戊:"무",己:"기",庚:"경",辛:"신",壬:"임",癸:"계" };
const CN2EL = { 甲:"목",乙:"목",丙:"화",丁:"화",戊:"토",己:"토",庚:"금",辛:"금",壬:"수",癸:"수" };

const JOHU_WHY = {
  목:"얼어붙은 기운을 풀거나 자라게 하는 자리입니다.",
  화:"차가운 사주를 덥히고 어둠을 밝히는 자리입니다.",
  토:"넘치는 물을 막고 중심을 잡아주는 자리입니다.",
  금:"무른 것을 벼리고 물길을 내는 자리입니다.",
  수:"뜨거운 사주를 식히고 마르지 않게 하는 자리입니다.",
};

/** 조후용신 — 일간과 월지만으로 정해진다 */
export function johuYongsin(saju) {
  const cell = JOHU[saju.dayMaster.stem]?.[saju.pillars.month.branch];
  if (!cell) return null;
  const [main, sub] = cell;
  const key = `${saju.dayMaster.stem}-${saju.pillars.month.branch}`;

  // 명식 안에 실제로 그 글자가 있는지 확인한다
  const stems = ["year","month","day","hour"]
    .map(k => saju.pillars[k]).filter(Boolean).map(p => p.stemCn);
  const hiddenKo = ["year","month","day","hour"]
    .map(k => saju.pillars[k]).filter(Boolean).flatMap(p => p.hidden);
  const hasStem   = stems.includes(main);
  const hasHidden = hiddenKo.includes(CN2KO[main]);

  return {
    main, mainKo: CN2KO[main], element: CN2EL[main],
    sub: sub.map(c => ({ cn: c, ko: CN2KO[c], element: CN2EL[c] })),
    present: hasStem ? "이 글자가 당신의 천간에 실제로 나와 있습니다. 조후가 이미 갖춰진 구성입니다."
           : hasHidden ? "이 글자가 지지 속에 숨어 있습니다. 드러나 있지는 않지만 쓸 수는 있는 자리입니다."
           : "이 글자가 명식에 없습니다. 타고나지 못한 것이라 대운과 세운에서 들어올 때를 기다리거나, 생활에서 그 기운 쪽으로 기울여 채워야 합니다.",
    strength: hasStem ? 2 : hasHidden ? 1 : 0,
    why: JOHU_WHY[CN2EL[main]],
    uncertain: JOHU_UNCERTAIN[key] || null,
  };
}

/** 억부와 조후를 나란히 놓고 어긋나는지 본다 */
export function yongsinCompare(saju) {
  const eokbu = analyzeStrength(saju);
  const johu = johuYongsin(saju);
  if (!johu) return { eokbu, johu: null, agree: null };
  const agree = johu.element === eokbu.yongsin;
  const conflict = johu.element === eokbu.gisin;
  return {
    eokbu, johu, agree, conflict,
    verdict: agree
      ? `두 관점이 같은 곳을 가리킵니다. 억부로도 조후로도 ${IGA(eokbu.yongsin)} 필요합니다. 이런 경우는 방향이 분명해서 흔들릴 일이 적습니다.`
      : conflict
      ? `두 관점이 정반대를 가리킵니다. 억부로는 ${IGA(eokbu.yongsin)} 필요한데, 조후로는 ${johu.main}, 곧 ${johu.element} 기운을 씁니다. 이런 경우는 계절의 한난이 강해 조후를 먼저 보는 쪽이 일반적이지만, 보는 관점에 따라 억부를 앞세우기도 합니다. 두 기운을 모두 염두에 두시는 편이 안전합니다.`
      : `억부로는 ${eokbu.yongsin}, 조후로는 ${johu.main}(${johu.element})입니다. 서로 부딪히지는 않으니 두 기운을 함께 쓰시면 됩니다.`,
  };
}

