export function modernFit(saju) {
  const dom = dominantSipsin(saju);
  const b = {}; saju.elements.forEach(e => b[e.name] = e.ratio);
  const sips = ["year","month","day","hour"].flatMap(k => {
    const p = saju.pillars[k]; if (!p) return [];
    return [p.stemSipsin, p.branchSipsin];
  });
  const scored = FIELD_DEF.map(f => {
    let s = 0;
    f.el.forEach((e, i) => { s += (b[e] || 0) * (i === 0 ? 1 : 0.7); });
    f.sip.forEach(x => { if (sips.includes(x)) s += 9; if (dom === x) s += 7; });
    return { ...f, score: Math.round(s) };
  }).sort((a, b2) => b2.score - a.score);

  /* 분야가 열한 개라 점수 차가 촘촘하다. 몇 점 차이를 순위 차이처럼 말하면 과장이 된다.
   * 최고점과 5점 안쪽은 '사실상 같은 무게'로 묶어 둔다. */
  const NEAR = 5;
  const top = scored[0].score;
  const tier = scored.map(f => ({ ...f, gap: top - f.score, near: top - f.score <= NEAR }));
  const leadPack = tier.filter(f => f.near);

  return {
    best: tier[0], second: tier[1], worst: tier[tier.length - 1], all: tier,
    near: NEAR, leadPack,
    tied: leadPack.length > 1,
    leadLine: leadPack.length > 1
      ? `${leadPack.map(f => f.k).join(", ")} ${leadPack.length}개가 ${tier[0].score}점 안팎으로 붙어 있습니다. 이 중에서는 순위보다 본인이 오래 할 수 있는 쪽을 고르시는 편이 맞습니다.`
      : `${tier[0].k}이 ${tier[0].score}점으로 2순위(${tier[1].k} ${tier[1].score}점)와 ${tier[1].gap}점 벌어져 있습니다. 비교적 또렷하게 한쪽으로 기운 명식입니다.`,
  };
}

/* ═══ 사주 성향 유형 — 네 축 16가지 ═════════════════
 *  축1 動靜  일간 음양        — 밖으로 먼저 / 안에서 먼저
 *  축2 發收  식상 vs 인성     — 내보내기 / 받아쌓기
 *  축3 實名  재성 vs 관성     — 숫자와 현실 / 명분과 질서
 *  축4 主和  비겁 vs 관성·인성 — 내가 정한다 / 맞춰 간다
 * ═══════════════════════════════════════════════ */
