/** 네 축으로 성향 유형을 뽑는다 */
export function personaType(saju) {
  const me = saju.dayMaster.element;
  const b = {}; saju.elements.forEach(e => b[e.name] = e.ratio);
  const sik = b[GEN[me]], inn = b[GEN_BY[me]], jae = b[CTL[me]], gwan = b[CTL_BY[me]], bi = b[me];

  const a1 = saju.dayMaster.yinyang === "양" ? "動" : "靜";
  const a2 = sik >= inn ? "發" : "收";
  const a3 = jae >= gwan ? "實" : "名";
  const a4 = bi >= (gwan + inn) * 0.85 ? "主" : "和";
  const code = a1 + a2 + a3 + a4;
  const type = TYPE_NAME[code];

  return {
    code, name: type.n, tagline: type.t,
    axes: [AXIS[a1], AXIS[a2], AXIS[a3], AXIS[a4]],
    letters: [a1, a2, a3, a4],
    pairs: [PAIR_NOTE[a1 + a2], PAIR_NOTE[a3 + a4]],
    nums: { 식상:sik, 인성:inn, 재성:jae, 관성:gwan, 비겁:bi },
    fit: `${AXIS[a2].job.split("—")[1].trim()} 쪽, 그리고 ${AXIS[a3].job.split("—")[1].trim()} 쪽입니다.`,
    good: `${AXIS[a4] === AXIS["主"] ? "맞춰주는 사람, 실행을 책임지는 사람" : "방향을 정해주는 사람, 결단이 빠른 사람"}과 잘 맞습니다.`,
    bad: `${AXIS[a4] === AXIS["主"] ? "똑같이 주도하려는 사람" : "방향 없이 맡기기만 하는 사람"}과는 소모가 큽니다.`,
    warns: [AXIS[a1].warn, AXIS[a2].warn, AXIS[a3].warn, AXIS[a4].warn],
  };
}

