/** 지금 하는 일과 명식 적성을 견준다 */
export function jobMatch(saju, jobValue) {
  if (!jobValue) return null;
  const opt = JOB_OPTIONS.find(o => o.v === jobValue);
  if (!opt) return null;
  const mf = modernFit(saju);
  const wm = workMode(saju);

  const total = mf.all.length;

  if (!opt.field) {
    return { label: opt.label, group: opt.g, rank: null, total, bridge: null,
      mode: `일하는 방식은 ${wm.key}입니다. ${wm.do[0]}`,
      all: mf.all.map((f, i) => ({ rank: i + 1, k: f.k, cur: false })),
      verdict:
        `**${LRO("'" + opt.label + "'")} 답해 주셨습니다.** ${opt.note || ""} `
        + `명식으로 보면 ${mf.leadLine} `
        + `${mf.best.why} **어디부터 해보면 되나.** ${mf.best.good.split(",")[0].trim()} 쪽이 가장 문턱이 낮습니다. ${mf.best.how} `
        + `반대로 ${LEUN(mf.worst.k)} 이 명식과 거리가 멉니다. 못 한다는 뜻이 아니라, 같은 성과를 내는 데 남보다 힘이 더 든다는 뜻입니다.` };
  }

  const idx = mf.all.findIndex(f => f.k === opt.field);
  const rank = idx + 1;
  const cur = mf.all[idx];
  /* 점수 차를 먼저 보되 순위도 함께 본다.
   * 2순위인데 '명식과 거리가 있다'고 말하면 틀린 말이 된다. */
  const upperCut = Math.max(3, Math.ceil(total / 3));
  const band = rank === 1 ? "top"
             : cur.near ? "near"
             : rank <= upperCut ? "upper"
             : cur.gap <= 22 ? "mid" : "low";

  const where = opt.g === opt.field
    ? `${LEUN("'" + opt.label + "'")} ${opt.field} 갈래입니다.`
    : `${opt.g} 안의 ${LEUN("'" + opt.label + "'")} ${opt.field} 갈래로 봅니다.`;
  const place = `${total}개 분야 중 ${rank}순위(${cur.score}점)`;
  let verdict;
  if (band === "top")
    verdict = `**지금 하는 일이 ${place}로 가장 위에 있습니다.** ${where} 이 명식이 가장 힘을 받는 자리라 방향을 바꿀 이유가 없습니다. 대신 ${cur.how} 그리고 ${cur.bad}`;
  else if (band === "near")
    verdict = `**지금 하는 일이 ${place}, 1순위와 ${cur.gap}점 차이입니다.** ${where} 이 정도 차이는 순위라고 부르기 어렵습니다. 지금 자리가 안 맞는 게 아니라 ${mf.best.k} 쪽과 거의 같은 무게로 붙어 있는 것이니, 옮길 이유보다 지금 자리를 더 파고들 이유가 큽니다. ${cur.how}`;
  else if (band === "upper")
    verdict = `**지금 하는 일이 ${place}로 상위권입니다.** ${where} 자리 자체는 맞습니다. 1순위 ${mf.best.k}보다 ${cur.gap}점 아래인데, 그 차이는 분야를 바꿔서가 아니라 방식을 바꿔서 메우는 편이 빠릅니다. ${cur.how}`;
  else if (band === "mid")
    verdict = `**지금 하는 일이 ${place}입니다.** ${where} 못 할 자리는 아니지만 1순위 ${mf.best.k}보다 ${cur.gap}점 아래라, 같은 성과를 내는 데 힘이 조금 더 듭니다. 지금 일에 ${mf.best.k}의 요소를 하나 붙이는 쪽이 옮기는 것보다 빠릅니다. ${mf.best.how}`;
  else
    verdict = `**지금 하는 일이 ${place}로, 1순위와 ${cur.gap}점 벌어져 있습니다.** ${where} 버티는 힘으로 해내고 계실 가능성이 큽니다. 위쪽은 ${mf.leadPack.map(f => f.k).join(", ")}입니다. 당장 옮기기 어렵다면 부업으로 한 줄 열어두고 1년을 보세요. ${mf.best.how}`;

  return {
    label: opt.label, group: opt.g, field: opt.field, rank, total,
    score: cur.score, gap: cur.gap, near: !!cur.near,
    verdict,
    bridge: (band === "top" || band === "near" || band === "upper") ? null
      : `지금 자리에서 ${mf.best.k} 쪽으로 다리를 놓는 가장 쉬운 방법은 ${mf.best.good.split(",")[0].trim()}입니다. 지금 하는 일을 소재로 삼으면 처음부터 시작하지 않아도 됩니다.`,
    mode: `일하는 방식은 ${wm.key}입니다. ${wm.do[0]}`,
    all: mf.all.map((f, i) => ({ rank: i + 1, k: f.k, score: f.score, gap: f.gap, cur: f.k === opt.field })),
  };
}

