/**
 * 택일 — 지정 기간에서 좋은 날과 피할 날을 뽑는다
 * @param {object} saju
 * @param {object} o  { purpose, from(Date), days(기본 90), count(기본 5) }
 */
export function buildTaekil(saju, o = {}) {
  const st = analyzeStrength(saju);
  const me = saju.dayMaster.element;
  const meYin = saju.dayMaster.yinyang === "양" ? 0 : 1;
  const P = TAEKIL_PURPOSE.find(p => p.v === (o.purpose || "contract")) || TAEKIL_PURPOSE[0];
  const start = o.from instanceof Date ? new Date(o.from) : new Date();
  const days = o.days || 90, count = o.count || 5;
  const dayBranch = saju.pillars.day.branch;

  const rows = [];
  for (let i = 0; i < days; i++) {
    const d = new Date(start.getFullYear(), start.getMonth(), start.getDate() + i);
    const g = dayGanji(d);
    const ss = sipsinOf(me, meYin, RGAN_EL[g.stem], RGAN_YIN[g.stem]);
    const bs = sipsinOf(me, meYin, RJI_EL[g.branch], RJI_YIN[g.branch]);
    const els = [RGAN_EL[g.stem], RJI_EL[g.branch]];
    const why = [], caution = [];
    let s = 50;

    if (P.want.includes(ss)) { s += 16; why.push(`천간에 ${ss}`); }
    if (P.want.includes(bs)) { s += 13; why.push(`지지에 ${bs}`); }
    if (P.avoid.includes(ss)) { s -= 17; caution.push(`천간에 ${ss}`); }
    if (P.avoid.includes(bs)) { s -= 14; caution.push(`지지에 ${bs}`); }
    if (els.includes(st.yongsin)) { s += 14; why.push(`용신 ${st.yongsin}`); }
    if (els.includes(st.gisin))   { s -= 12; caution.push(`기신 ${st.gisin}`); }
    if (YUKHAP[dayBranch] === g.branch) { s += 12; why.push("일지와 육합"); }
    if (SAMHAP[dayBranch] === SAMHAP[g.branch] && dayBranch !== g.branch) { s += 7; why.push("일지와 삼합"); }
    if (CHUNG[dayBranch] === g.branch) { s -= 20; caution.push("일지를 충함"); }
    if (HYEONG[dayBranch] === g.branch) { s -= 10; caution.push("일지와 형"); }
    if (saju.gongmang.includes(g.branch)) { s -= 13; caution.push("공망일"); }
    s = Math.max(5, Math.min(97, Math.round(s)));

    rows.push({
      date: `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`,
      label: `${d.getMonth()+1}월 ${d.getDate()}일`,
      dow: ["일","월","화","수","목","금","토"][d.getDay()],
      ganji: g.stemCn + g.branchCn,
      sipsin: `${ss}·${bs}`,
      score: s, grade: GRADE(s),
      why: why.join(", ") || "특별히 받쳐주는 요소 없음",
      caution: caution.join(", ") || "",
    });
  }

  const best = [...rows].sort((a,b) => b.score - a.score).slice(0, count)
                        .sort((a,b) => a.date.localeCompare(b.date));
  const worst = [...rows].sort((a,b) => a.score - b.score).slice(0, 3)
                         .sort((a,b) => a.date.localeCompare(b.date));

  return {
    purpose: P.label, tip: P.tip,
    range: `${rows[0].label} ~ ${rows[rows.length-1].label}`,
    best, worst, all: rows,
    note: `일간 ${saju.dayMaster.stemCn}을 기준으로 ${days}일치 일진을 모두 계산해 ${P.label}에 맞는 날을 골랐습니다. 점수는 목적에 맞는 십신, 용신·기신, 일지와의 합충, 공망을 합산한 값입니다.`,
  };
}

