// 삼합 그룹의 생지를 충하는 지지부터 3년. 해묘미생 → 사오미년
const SAMJAE_MAP = {
  해:["사","오","미"], 묘:["사","오","미"], 미:["사","오","미"],
  인:["신","유","술"], 오:["신","유","술"], 술:["신","유","술"],
  사:["해","자","축"], 유:["해","자","축"], 축:["해","자","축"],
  신:["인","묘","진"], 자:["인","묘","진"], 진:["인","묘","진"],
};
const SAMJAE_STAGE = ["들삼재","눌삼재","날삼재"];
const SAMJAE_TEXT = {
  들삼재:"삼재가 들어오는 첫해입니다. 큰일이 터진다기보다 판이 흔들리기 시작하는 시기라, 새로 벌이는 일은 한 박자 늦추고 기존의 것을 단단히 하는 편이 낫습니다.",
  눌삼재:"삼재가 가장 오래 머무는 해입니다. 일이 더디고 막히는 느낌이 잦지만, 이 해를 조용히 통과한 사람은 다음 해에 크게 벌어집니다. 큰 계약과 이사, 동업 결정은 미루는 쪽을 권합니다.",
  날삼재:"삼재가 빠져나가는 마지막 해입니다. 앞선 두 해의 여파가 정리되는 시기라 끝맺음에 어울립니다. 새로 시작할 준비를 이 해 안에 마쳐두면 다음 해가 수월합니다.",
  없음:"올해는 삼재에 해당하지 않습니다. 외부에서 오는 큰 액운 없이 본인의 선택이 결과를 결정하는 해입니다.",
};

function samjaeOf(yearBranchOfBirth, yearBranch) {
  const arr = SAMJAE_MAP[yearBranchOfBirth];
  const i = arr.indexOf(yearBranch);
  return i < 0 ? { on:false, stage:"없음", text:SAMJAE_TEXT["없음"] }
               : { on:true, stage:SAMJAE_STAGE[i], text:SAMJAE_TEXT[SAMJAE_STAGE[i]] };
}

