  관성:"눌리는 관계입니다. 상대가 기준을 쥐고 있어 처음엔 편한데, 시간이 지나면 내 자리가 사라집니다.",
  인성:"받기만 하는 관계입니다. 편안한 대신 스스로 결정하는 힘이 줄어들고, 그 사실을 늦게 알아차립니다.",
