/* ═══ 인연 ══════════════════════════════════════════ */
// 육합
const YUKHAP = { 자:"축", 축:"자", 인:"해", 해:"인", 묘:"술", 술:"묘",
                 진:"유", 유:"진", 사:"신", 신:"사", 오:"미", 미:"오" };
// 삼합 그룹
const SAMHAP = { 신:"신자진", 자:"신자진", 진:"신자진", 해:"해묘미", 묘:"해묘미", 미:"해묘미",
                 인:"인오술", 오:"인오술", 술:"인오술", 사:"사유축", 유:"사유축", 축:"사유축" };
// 충
const CHUNG = { 자:"오", 오:"자", 축:"미", 미:"축", 인:"신", 신:"인",
                묘:"유", 유:"묘", 진:"술", 술:"진", 사:"해", 해:"사" };

/** 배우자성의 오행이 그리는 인상 */
const PARTNER_LOOK = {
  목:"키가 있는 편이고 자세가 곧습니다. 첫인상이 단정하고, 말보다 태도에서 사람이 읽힙니다.",
  화:"표정이 밝고 눈에 띄는 사람입니다. 어디에 있어도 존재가 먼저 도착하는 쪽입니다.",
  토:"체격이 든든하고 인상이 편안합니다. 화려하지 않은데 곁에 있으면 안정되는 사람입니다.",
  금:"이목구비가 또렷하고 깔끔합니다. 차가워 보이지만 겪어보면 의리가 있는 쪽입니다.",
  수:"분위기가 있고 눈매가 깊습니다. 처음엔 알기 어렵고 시간이 지나야 진면목이 보입니다.",
};
const PARTNER_JOB = {
  목:"교육, 출판, 기획, 의료, 목재·섬유 계통이나 무언가를 키우고 가르치는 일",
  화:"방송, 홍보, 예술, 뷰티, IT, 전기·에너지 계통이나 사람 앞에 서는 일",
  토:"부동산, 건설, 농업, 중개, 공공기관이나 사람과 자원을 연결하는 일",
  금:"금융, 법률, 제조, 의료기기, 군경이나 기준을 다루고 판단하는 일",
  수:"연구, 유통, 무역, 요식, 물류나 흐름을 다루고 분석하는 일",
};
const PARTNER_CHAR = {
  정재:"성실하고 계획적인 사람입니다. 화려하지 않지만 약속을 지키고, 살림과 돈 관리를 안정적으로 합니다.",
  편재:"활동적이고 사교적인 사람입니다. 씀씀이가 크고 사람을 좋아해서 함께 있으면 즐겁지만, 한곳에 묶이기를 답답해합니다.",
  정관:"반듯하고 책임감 있는 사람입니다. 조직에서 인정받는 쪽이고, 가정을 지키는 일을 당연하게 여깁니다.",
  편관:"강단 있고 추진력 있는 사람입니다. 의지할 만한 대신 고집이 있어서, 부딪힐 때는 세게 부딪힙니다.",
};
const SPOUSE_PALACE = {
  비견:"배우자 자리에 비겁이 앉아 서로 독립적인 관계가 됩니다. 각자의 영역을 존중할 때 오래갑니다.",
  겁재:"배우자 자리에 겁재가 앉아 경쟁하듯 부딪히기 쉽습니다. 돈 문제를 분명히 해두는 것이 중요합니다.",
  식신:"배우자 자리가 편안합니다. 함께 있을 때 잘 먹고 잘 웃는 관계가 됩니다.",
  상관:"배우자에게 할 말을 다 하는 편입니다. 솔직한 대신 상대가 상처받지 않게 표현을 다듬어야 합니다.",
  편재:"배우자 복이 활달하게 나타납니다. 다만 한 사람에게 오래 머무는 연습이 필요합니다.",
  정재:"배우자 자리가 안정적입니다. 결혼 후에 오히려 자리가 잡히는 쪽입니다.",
  편관:"배우자가 강한 사람일 가능성이 큽니다. 기대는 만큼 눌리기도 하니 균형이 관건입니다.",
  정관:"배우자 자리가 반듯합니다. 결혼이 삶의 질서를 만들어주는 쪽입니다.",
  편인:"배우자와 생각으로 통하는 관계입니다. 대신 감정 표현이 적어 오해가 쌓이기 쉽습니다.",
  정인:"배우자에게 보살핌을 받는 자리입니다. 기대는 것이 편해지면 관계가 한쪽으로 기울 수 있습니다.",
};

/**
 * 인연 리포트 — 배우자상, 인연이 들어오는 해, 결혼 적기
 */
export function buildLoveReport(saju, opts = {}) {
  const st = analyzeStrength(saju);
  const me = saju.dayMaster.element;
  const meYin = saju.dayMaster.yinyang === "양" ? 0 : 1;
  const isMale = saju.input.gender === "M";

  // 배우자성: 남 재성, 여 관성
  const pEl = isMale ? CTL[me] : CTL_BY[me];
  const pGroup = isMale ? "재성" : "관성";
  const pNames = GROUP[pGroup];

  // 명식 어느 자리에 배우자성이 있는가
  const spots = [];
  [["year","년주"],["month","월주"],["day","일주"],["hour","시주"]].forEach(([k,label]) => {
    const p = saju.pillars[k]; if (!p) return;
    if (pNames.includes(p.stemSipsin))   spots.push({ pos:label, where:"천간", sipsin:p.stemSipsin });
    if (pNames.includes(p.branchSipsin)) spots.push({ pos:label, where:"지지", sipsin:p.branchSipsin });
  });

  const dayBranch = saju.pillars.day.branch;
  const palace = saju.pillars.day.branchSipsin;

  // 나이차: 배우자성이 놓인 자리로 본다
  let ageGap;
  const posSet = new Set(spots.map(s => s.pos));
  if (!spots.length)       ageGap = "명식에 배우자성이 드러나 있지 않습니다. 인연이 늦게 오거나, 내가 먼저 찾아 나서야 만나는 구조입니다.";
  else if (posSet.has("년주")) ageGap = "배우자성이 년주에 놓여 연상 쪽 인연이 유력합니다. 나이 차가 있는 만남이거나, 사회적으로 앞서 있는 상대일 수 있습니다.";
  else if (posSet.has("시주")) ageGap = "배우자성이 시주에 놓여 연하 쪽 인연이 유력합니다. 늦게 만나는 인연이 더 잘 맞습니다.";
  else if (posSet.has("일주")) ageGap = "배우자성이 일주에 놓여 또래 인연이 유력합니다. 가까운 자리에서 만나는 사람일 가능성이 큽니다.";
  else                         ageGap = "배우자성이 월주에 놓여 또래이거나 두세 살 차이의 인연이 유력합니다. 직장이나 학업처럼 일상 반경 안에서 만납니다.";

  const mainSipsin = spots.length ? spots[0].sipsin : pNames[1];

  // 인연이 오가는 해 — 만 18세부터 앞으로 15년까지 전 구간을 본다
  const thisYear = opts.fromYear ?? new Date().getFullYear();
  const nowAge = Math.floor(exactAge(saju));
  const startYear = saju.solar.year + 18;
  const endYear = thisYear + 15;
  const years = [];
  for (let y = startYear; y <= endYear; y++) {
    const si = ((y - 4) % 10 + 10) % 10, bi = ((y - 4) % 12 + 12) % 12;
    const ys = RGAN[si], yb = RJI[bi];
    const ss = sipsinOf(me, meYin, RGAN_EL[ys], RGAN_YIN[ys]);
    const bs = sipsinOf(me, meYin, RJI_EL[yb],  RJI_YIN[yb]);
    const reasons = [];
    let sc = 0;
    if (pNames.includes(ss)) { sc += 30; reasons.push(`천간에 ${ss}`); }
    if (pNames.includes(bs)) { sc += 26; reasons.push(`지지에 ${bs}`); }
    if (YUKHAP[dayBranch] === yb) { sc += 28; reasons.push(`배우자궁 ${saju.pillars.day.branchCn}과 육합`); }
    if (SAMHAP[dayBranch] === SAMHAP[yb] && dayBranch !== yb) { sc += 16; reasons.push("배우자궁과 삼합"); }
    if (CHUNG[dayBranch] === yb) { sc -= 18; reasons.push("배우자궁을 충함"); }
    const a = y - saju.solar.year;
    const dae = saju.daeun.list.find(d => a >= d.startAge && a < d.startAge + 10);
    if (dae && pNames.includes(dae.sipsin)) { sc += 14; reasons.push(`${dae.sipsin} 대운 중`); }
    years.push({ year:y, gapjaCn:RGAN_CN[si] + RJI_CN[bi], age:a, score:sc, reasons });
  }

  // 나이대별 성격 부여
  const phaseOf = (a) =>
    a < 24 ? "이른 인연"
  : a < 34 ? "결혼 적령"
  : a < 44 ? "늦은 인연"
  : a < 55 ? "만혼 또는 재혼" : "늦은 동반";

  const strong = years.filter(y => y.score >= 30);
  const pastAll   = strong.filter(y => y.year <  thisYear);
  const futureAll = strong.filter(y => y.year >= thisYear);

  // 지난 인연 해는 검증용으로 가까운 것 세 개
  const pastYears = pastAll.slice(-3).map(y => ({ ...y, phase: phaseOf(y.age) }));
  // 앞으로 열리는 해는 가까운 것 네 개
  const futureYears = futureAll.slice(0, 4).map(y => ({ ...y, phase: phaseOf(y.age) }));
  const bestYears = futureYears.length ? futureYears
    : years.filter(y => y.year >= thisYear).sort((a,b) => b.score - a.score).slice(0,2)
           .sort((a,b) => a.year - b.year).map(y => ({ ...y, phase: phaseOf(y.age) }));

  // 나이에 따른 전제
  const stage =
    nowAge < 24 ? { key:"이른", note:"아직 인연이 본격적으로 열리는 구간에 들어서지 않았습니다. 앞으로 오는 해를 중심으로 보시면 됩니다." }
  : nowAge < 34 ? { key:"적령", note:"인연이 가장 활발하게 오가는 구간입니다. 지난 해들 중에도 열렸던 해가 있었을 가능성이 높습니다." }
  : nowAge < 44 ? { key:"만혼", note:"이미 지나온 인연의 해가 여럿 있습니다. 앞으로 오는 해는 첫 인연보다 늦은 결혼이나 재혼, 또는 오래 이어질 동반의 성격을 띱니다." }
  : { key:"재혼", note:"앞으로 오는 해는 첫 인연을 가리키기보다 재혼이나 늦은 동반, 또는 오래 알던 사람과의 관계 변화를 가리키는 경우가 많습니다." };

  // 결혼 적기 대운
  const marryDaeun = saju.daeun.list.filter(d => pNames.includes(d.sipsin) && d.startAge < 60);

  return {
    title: isMale ? "내 배우자는 어떤 사람일까" : "내 배우자는 어떤 사람일까",
    subtitle: `${isMale ? "남자에게 배우자는 재성" : "여자에게 배우자는 관성"}으로 봅니다. 당신에게 그 자리는 ${pEl}입니다.`,
    partner: {
      element: pEl,
      sipsin: mainSipsin,
      look: PARTNER_LOOK[pEl],
      job: PARTNER_JOB[pEl],
      character: PARTNER_CHAR[mainSipsin] || PARTNER_CHAR[pNames[1]],
      ageGap,
      count: spots.length,
      countText: spots.length === 0
        ? "명식에 배우자성이 없습니다. 인연의 수가 적은 대신 한 번 만나면 깊게 갑니다. 조건을 따지기보다 먼저 다가가는 쪽이 유리합니다."
        : spots.length === 1
        ? "배우자성이 하나입니다. 인연이 여럿 스쳐가기보다 결정적인 한 사람이 있는 구조입니다."
        : spots.length === 2
        ? "배우자성이 둘입니다. 진지한 인연이 두어 번 오니, 시기를 알고 고르는 것이 중요합니다."
        : "배우자성이 여럿입니다. 인연이 자주 오가는 구조라 선택이 관건이고, 급하게 정하면 되돌아오는 일이 생깁니다.",
    },
    palace: { branch: saju.pillars.day.branchCn, sipsin: palace, text: SPOUSE_PALACE[palace] },
    years: bestYears,
    pastYears,
    stage,
    nowAge,
    marryDaeun,
    tip: st.level === "신약"
      ? "신약 구성이라 상대의 영향을 크게 받습니다. 누구를 만나느냐가 삶의 방향을 거의 결정하니, 조건보다 사람의 결을 보세요."
      : "신강 구성이라 스스로 끌고 가는 힘이 있습니다. 기대기보다 함께 걷는 상대를 찾을 때 오래갑니다.",
  };
}

/* ═══ 신년운세 시즌 ═════════════════════════════════ */
/** 12~2월은 신년운세 시즌. 다음 해를 기본값으로 잡는다 */
export function newYearSeason(ref) {
  const d = ref instanceof Date ? ref : new Date();
  const m = d.getMonth() + 1, y = d.getFullYear();
  if (m === 12)          return { on:true,  targetYear: y + 1, phase:"프리오픈" };
  if (m === 1 || m === 2) return { on:true,  targetYear: y,     phase:"성수기" };
  if (m === 11)          return { on:true,  targetYear: y + 1, phase:"얼리버드" };
  return { on:false, targetYear: y, phase:"평시" };
}

/* ═══ 일진 / 오늘의 운세 ════════════════════════════ */
function jdnOf(y, m, d) {
  const a = Math.floor((14 - m) / 12), yy = y + 4800 - a, mm = m + 12 * a - 3;
  return d + Math.floor((153 * mm + 2) / 5) + 365 * yy
           + Math.floor(yy / 4) - Math.floor(yy / 100) + Math.floor(yy / 400) - 32045;
}
/** 특정 날짜의 일진 간지 */
export function dayGanji(date) {
  const d = date instanceof Date ? date : new Date();
  const idx = (jdnOf(d.getFullYear(), d.getMonth() + 1, d.getDate()) + 49) % 60;
  return { idx, stem: RGAN[idx % 10], branch: RJI[idx % 12],
           stemCn: RGAN_CN[idx % 10], branchCn: RJI_CN[idx % 12] };
}

const DAILY_OPEN = {
  대길:"오늘은 문이 열려 있습니다.",
  길:"오늘은 흐름이 순합니다.",
  평:"오늘은 무난합니다.",
  주의:"오늘은 조심스럽게 가세요.",
};
const DAILY_BODY = {
  비견:"내 뜻대로 밀어붙이기 좋은 날입니다. 남의 결정을 기다리지 말고 먼저 정하세요.",
  겁재:"지출과 경쟁이 늘어나는 날입니다. 오늘 결제는 한 번 더 생각하세요.",
  식신:"손에서 뭔가 나오는 날입니다. 미뤄둔 일을 꺼내면 생각보다 잘 끝납니다.",
  상관:"말이 앞서는 날입니다. 하고 싶은 말을 한 번 삼키면 오늘이 편안해집니다.",
  편재:"기회가 스치는 날입니다. 사람을 만나되 큰 결정은 서두르지 마세요.",
  정재:"실속이 붙는 날입니다. 꼼꼼히 챙기면 그만큼 남습니다.",
  편관:"부담이 몰리는 날입니다. 무리하면 몸이 먼저 반응하니 속도를 줄이세요.",
  정관:"책임이 오는 날입니다. 맡게 되는 일을 피하지 마세요.",
  편인:"생각이 깊어지는 날입니다. 새로 벌이기보다 정리하고 배우기에 맞습니다.",
  정인:"도움이 들어오는 날입니다. 혼자 끌어안지 말고 물어보세요.",
};
const HOUR_LABEL = [
  ["자시","23~01시"],["축시","01~03시"],["인시","03~05시"],["묘시","05~07시"],
  ["진시","07~09시"],["사시","09~11시"],["오시","11~13시"],["미시","13~15시"],
  ["신시","15~17시"],["유시","17~19시"],["술시","19~21시"],["해시","21~23시"],
];

/** 오늘의 운세 — 일진 기반. 무료 콘텐츠이자 재방문 축 */
export function buildDailyReport(saju, date) {
  const d = date instanceof Date ? date : new Date();
  const st = analyzeStrength(saju);
  const me = saju.dayMaster.element;
  const meYin = saju.dayMaster.yinyang === "양" ? 0 : 1;
  const roles = elementRoles(me);

  const g = dayGanji(d);
  const ss = sipsinOf(me, meYin, RGAN_EL[g.stem], RGAN_YIN[g.stem]);
  const bs = sipsinOf(me, meYin, RJI_EL[g.branch], RJI_YIN[g.branch]);
  const els = [RGAN_EL[g.stem], RJI_EL[g.branch]];

  const dayBranch = saju.pillars.day.branch;
  let base = 50;
  if (els.includes(st.yongsin)) base += 20;
  if (els.includes(st.gisin))   base -= 16;
  if (YUKHAP[dayBranch] === g.branch) base += 12;
  if (CHUNG[dayBranch]  === g.branch) base -= 14;
  if (saju.gongmang.includes(g.branch)) base -= 8;
  if (saju.sinsal["천을귀인"]) base += 3;
  base = Math.max(12, Math.min(96, base));
  const grade = GRADE(base);

  const sub = (targets, bonus) => {
    let s = base - 7;
    if (targets.includes(ss)) s += 15; else s -= 3;
    if (targets.includes(bs)) s += 11; else s -= 2;
    s += (bonus || 0);
    return Math.max(10, Math.min(97, Math.round(s)));
  };
  const isMale = saju.input.gender === "M";

  // 좋은 시간대
  const hours = HOUR_LABEL.map(([name, range], i) => {
    const hb = RJI[i];
    let s = 50;
    if (RJI_EL[hb] === st.yongsin) s += 22;
    if (RJI_EL[hb] === st.gisin)   s -= 18;
    if (YUKHAP[dayBranch] === hb)  s += 10;
    if (CHUNG[dayBranch]  === hb)  s -= 12;
    return { name, range, score: Math.max(10, Math.min(95, s)) };
  });
  const bestHour  = [...hours].sort((a,b) => b.score - a.score)[0];
  const worstHour = [...hours].sort((a,b) => a.score - b.score)[0];

  const lk = LUCKY[st.yongsin];
  const stamp = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;

  return {
    date: stamp,
    label: `${d.getMonth()+1}월 ${d.getDate()}일`,
    ganji: g.stemCn + g.branchCn,
    ganjiKo: g.stem + g.branch,
    sipsin: ss, branchSipsin: bs,
    score: base, grade,
    headline: `${DAILY_OPEN[grade]} ${DAILY_BODY[ss]}`,
    detail: [
      `오늘 일진은 ${g.stemCn}${g.branchCn}이고, 당신의 일간 ${saju.dayMaster.stemCn} 기준으로 ${ss}·${bs}에 해당합니다.`,
      els.includes(st.yongsin)
        ? `용신 ${st.yongsin}이 닿는 날이라 평소보다 힘이 실립니다. 미뤄둔 일을 오늘 처리하세요.`
        : els.includes(st.gisin)
        ? `기신 ${st.gisin}이 겹치는 날이라 무리가 그대로 돌아옵니다. 욕심을 줄이면 무난합니다.`
        : `용신과도 기신과도 닿지 않아 외부 변수가 적은 날입니다.`,
      YUKHAP[dayBranch] === g.branch ? "일지와 육합을 이루는 날이라 사람 만나는 일이 잘 풀립니다." :
      CHUNG[dayBranch]  === g.branch ? "일지를 충하는 날이라 마음이 들썩입니다. 큰 결정은 내일로 미루세요." : "",
    ].filter(Boolean),
    fields: [
      { name:"애정", score: sub(isMale ? GROUP.재성 : GROUP.관성, saju.sinsal["도화"] ? 4 : 0) },
      { name:"금전", score: sub(GROUP.재성) },
      { name:"일",   score: sub(GROUP.관성) },
      { name:"건강", score: sub(GROUP.인성, ["편관","상관"].includes(ss) ? -8 : 0) },
    ].map(f => ({ ...f, grade: GRADE(f.score) })),
    bestHour, worstHour,
    lucky: { color: lk.color, num: lk.num, dir: lk.dir, food: lk.food },
    advice: base >= 62
      ? "오늘 같은 날은 미루지 않는 것이 전부입니다. 하려던 것을 오늘 안에 하세요."
      : base >= 45
      ? "특별할 것 없는 하루가 가장 쌓기 좋은 하루입니다. 하던 것을 그대로 하세요."
      : "오늘은 잘 지나가는 것이 성과입니다. 새로 벌이지 말고 마무리만 하세요.",
  };
}

/* ═══ 궁합 ══════════════════════════════════════════ */
// 천간합
const CHEONHAP = { 갑:"기", 기:"갑", 을:"경", 경:"을", 병:"신", 신:"병", 정:"임", 임:"정", 무:"계", 계:"무" };
// 지지 형
const HYEONG = { 인:"사", 사:"신", 신:"인", 축:"술", 술:"미", 미:"축", 자:"묘", 묘:"자" };

const COMPAT_GRADE = (s) => s >= 82 ? "천생연분" : s >= 68 ? "좋은 인연" : s >= 52 ? "노력하면 좋은 사이" : s >= 38 ? "부딪히는 사이" : "쉽지 않은 인연";

/** 궁합 리포트 — 두 사람의 명식을 견준다 */
export function buildCompatReport(a, b, opts = {}) {
  const nameA = opts.nameA || "나", nameB = opts.nameB || "상대";
  const stA = analyzeStrength(a), stB = analyzeStrength(b);
  const elA = a.dayMaster.element, elB = b.dayMaster.element;
  const dsA = a.pillars.day.stem,  dsB = b.pillars.day.stem;
  const dbA = a.pillars.day.branch, dbB = b.pillars.day.branch;

  const notes = [];
  let score = 50;

  // 1) 일간 관계
  let stemRel;
  if (CHEONHAP[dsA] === dsB) { score += 16; stemRel = "천간합";
    notes.push(`일간 ${a.pillars.day.stemCn}과 ${b.pillars.day.stemCn}이 천간합을 이룹니다. 서로를 끌어당기는 힘이 기본으로 깔린 관계입니다.`); }
  else if (GEN[elA] === elB) { score += 12; stemRel = "내가 상대를 생함";
    notes.push(`${nameA}의 ${IGA(elA)} ${nameB}의 ${EUL(elB)} 살립니다. 주는 쪽이 ${nameA}이라, 아끼는 마음이 자연스럽게 나오는 대신 한쪽으로 기울 수 있습니다.`); }
  else if (GEN[elB] === elA) { score += 12; stemRel = "상대가 나를 생함";
    notes.push(`${nameB}의 ${IGA(elB)} ${nameA}의 ${EUL(elA)} 살립니다. ${nameA}이 기대게 되는 구조라 편안하지만, 고마움을 표현하지 않으면 상대가 지칩니다.`); }
  else if (elA === elB) { score += 6; stemRel = "같은 오행";
    notes.push(`두 사람의 일간이 같은 ${elA}입니다. 말이 잘 통하고 취향이 겹치는 대신, 같은 약점도 공유해서 위기 때 함께 흔들립니다.`); }
  else if (CTL[elA] === elB) { score -= 8; stemRel = "내가 상대를 극함";
    notes.push(`${nameA}의 ${IGA(elA)} ${nameB}의 ${EUL(elB)} 누릅니다. ${nameA}의 말이 의도보다 세게 가 닿으니 표현을 다듬어야 합니다.`); }
  else { score -= 8; stemRel = "상대가 나를 극함";
    notes.push(`${nameB}의 ${IGA(elB)} ${nameA}의 ${EUL(elA)} 누릅니다. ${nameA}이 눌리는 느낌을 받기 쉬우니 거리와 경계가 필요합니다.`); }

  // 2) 일지(배우자궁) 관계
  let branchRel = "무관";
  if (YUKHAP[dbA] === dbB) { score += 18; branchRel = "육합";
    notes.push(`배우자궁 ${a.pillars.day.branchCn}과 ${b.pillars.day.branchCn}이 육합입니다. 궁합에서 가장 좋게 보는 자리로, 함께 있을 때 편안함을 느낍니다.`); }
  else if (SAMHAP[dbA] === SAMHAP[dbB] && dbA !== dbB) { score += 13; branchRel = "삼합";
    notes.push("배우자궁이 삼합 그룹으로 묶입니다. 목표와 방향이 같아 같이 무언가를 만들어가기에 좋습니다."); }
  else if (CHUNG[dbA] === dbB) { score -= 16; branchRel = "충";
    notes.push(`배우자궁이 서로 충합니다. 끌림이 강한 대신 부딪힘도 강해서, 가까워질수록 다툼이 늘어나는 구조입니다. 물리적 거리와 각자의 시간이 약이 됩니다.`); }
  else if (HYEONG[dbA] === dbB) { score -= 10; branchRel = "형";
    notes.push("배우자궁이 형을 이룹니다. 말로 상처를 주고받기 쉬우니, 감정이 올라올 때 그 자리에서 결론내지 않는 규칙이 필요합니다."); }
  else if (dbA === dbB) { score += 7; branchRel = "같은 지지";
    notes.push("배우자궁이 같습니다. 생활 리듬이 비슷해 함께 사는 데 마찰이 적습니다."); }

  // 3) 용신 교환 — 궁합의 실질
  const ratioB = {}; b.elements.forEach(e => ratioB[e.name] = e.ratio);
  const ratioA = {}; a.elements.forEach(e => ratioA[e.name] = e.ratio);
  const givesAtoB = ratioA[stB.yongsin] >= 25;
  const givesBtoA = ratioB[stA.yongsin] >= 25;
  if (givesBtoA) { score += 12;
    notes.push(`${nameA}에게 필요한 ${stA.yongsin} 기운을 ${nameB}${hasJong(nameB)?"이":"가"} ${ratioB[stA.yongsin]}%로 넉넉히 가지고 있습니다. 곁에 있는 것만으로 부족한 자리가 채워집니다.`); }
  if (givesAtoB) { score += 12;
    notes.push(`${nameB}에게 필요한 ${stB.yongsin} 기운을 ${nameA}${hasJong(nameA)?"이":"가"} ${ratioA[stB.yongsin]}%로 채워줍니다.`); }
  if (!givesAtoB && !givesBtoA)
    notes.push("서로의 부족한 기운을 직접 채워주지는 않습니다. 기대서 해결되는 관계가 아니라 각자 채우고 만나는 관계입니다.");

  // 4) 신강약 조합
  if (stA.level === "신강" && stB.level === "신약") notes.push(`${nameA}${hasJong(nameA)?"이":"가"} 끌고 ${nameB}${hasJong(nameB)?"이":"가"} 따르는 구도입니다. 방향이 맞으면 빠르고, 어긋나면 ${nameB}${hasJong(nameB)?"이":"가"} 소모됩니다.`);
  else if (stA.level === "신약" && stB.level === "신강") notes.push(`${nameB}이 끌고 ${nameA}이 기대는 구도입니다. ${nameA}에게는 안정적이지만 의존이 깊어지지 않게 조심하세요.`);
  else if (stA.level === "신강" && stB.level === "신강") { score -= 6; notes.push("둘 다 신강이라 양보가 잘 안 됩니다. 영역을 나눠 각자 결정권을 갖는 방식이 맞습니다."); }
  else if (stA.level === "신약" && stB.level === "신약") { score -= 4; notes.push("둘 다 신약이라 서로 기대려 합니다. 바깥에 함께 기댈 구조를 만들어두는 편이 낫습니다."); }

  score = Math.max(10, Math.min(97, Math.round(score)));

  const sub = (base, plus) => Math.max(10, Math.min(97, Math.round(base + plus)));
  const fields = [
    { key:"love",  name:"연애 궁합", icon:"緣",
      score: sub(score, branchRel === "육합" ? 6 : branchRel === "충" ? -6 : 0),
      text: branchRel === "육합" ? "함께 있을 때 말이 없어도 편안한 사이입니다. 연애 단계에서 진도가 자연스럽게 나갑니다."
          : branchRel === "충" ? "끌림이 강해 빠르게 가까워지지만 그만큼 부딪힙니다. 속도를 늦추는 쪽이 오래갑니다."
          : "무난하게 시작하는 사이입니다. 극적인 끌림보다 시간이 쌓이며 깊어지는 쪽입니다." },
    { key:"marry", name:"결혼 궁합", icon:"婚",
      score: sub(score, (givesAtoB || givesBtoA) ? 8 : -4),
      text: (givesAtoB || givesBtoA)
          ? "부족한 기운을 서로 채워주는 조합이라 함께 살수록 안정됩니다. 결혼으로 갈수록 유리해지는 궁합입니다."
          : "연애보다 결혼에서 차이가 드러납니다. 생활 방식과 돈 문제를 미리 합의해두면 크게 흔들리지 않습니다." },
    { key:"money", name:"재물 궁합", icon:"財",
      score: sub(score, ratioA[CTL[elA]] + ratioB[CTL[elB]] >= 40 ? 7 : -3),
      text: "함께 벌고 함께 쓰는 구조가 맞는지 봅니다. 통장을 합칠지 나눌지를 초반에 정해두면 갈등이 줄어듭니다." },
    { key:"talk",  name:"대화 궁합", icon:"言",
      score: sub(score, stemRel === "천간합" ? 8 : stemRel.includes("극") ? -7 : 2),
      text: stemRel === "천간합" ? "말이 잘 통합니다. 설명하지 않아도 의도가 전달되는 편입니다."
          : stemRel.includes("극") ? "같은 말도 다르게 들리는 조합입니다. 결론부터 말하기보다 이유를 먼저 말하는 쪽이 안전합니다."
          : "서로 다른 방식으로 말하지만 알아들을 수는 있는 사이입니다." },
    { key:"long",  name:"장기 궁합", icon:"久",
      score: sub(score, branchRel === "형" ? -8 : branchRel === "삼합" ? 7 : 0),
      text: "10년 뒤에도 같이 있을 수 있는가를 봅니다. 대운이 엇갈리는 시기를 미리 알면 그 구간을 견디기 쉬워집니다." },
  ].map(f => ({ ...f, grade: COMPAT_GRADE(f.score) }));

  return {
    score, grade: COMPAT_GRADE(score),
    stemRel, branchRel,
    a: { gapja: a.pillars.day.gapjaCn, el: elA, level: stA.level, yongsin: stA.yongsin },
    b: { gapja: b.pillars.day.gapjaCn, el: elB, level: stB.level, yongsin: stB.yongsin },
    notes, fields,
    closing: score >= 68
      ? "좋은 궁합입니다. 다만 궁합이 좋다고 저절로 되는 것은 없습니다. 잘 맞는 조합일수록 노력이 티가 나지 않아 서로 당연하게 여기기 쉽습니다."
      : score >= 52
      ? "노력이 필요한 조합입니다. 궁합은 시작 조건이지 결론이 아닙니다. 어디서 부딪히는지를 알고 만나면 그 지점이 오히려 강점이 됩니다."
      : "쉽지 않은 조합으로 나옵니다. 다만 사주가 맞지 않아도 오래 사는 사람들이 있습니다. 차이를 고치려 들지 않고 인정하는 것이 이 궁합의 유일한 방법입니다.",
  };
}

/* ═══ 재물 전용 블록 ════════════════════════════════ */
const WEALTH_STYLE = {
  편재:"큰 판에서 버는 방식입니다. 한 번에 크게 움직이는 돈을 다루고, 기회를 보는 눈이 밝습니다. 대신 고정 수입만으로는 답답해져서 결국 벌리는 쪽으로 갑니다.",
  정재:"쌓아서 버는 방식입니다. 계획을 세우고 매달 들어오는 구조를 만드는 쪽이 맞습니다. 큰 한 방을 노리면 오히려 잃습니다.",
  혼합:"큰 돈과 작은 돈이 섞여 있습니다. 안정된 수입선을 깔아두고 그 위에서 기회를 노리는 이중 구조가 가장 잘 맞습니다.",
  없음:"명식에 재성이 드러나 있지 않습니다. 돈을 직접 쫓는 구조가 아니라, 일과 재능이 먼저 서면 돈이 따라오는 쪽입니다. 돈만 보고 움직이면 오히려 어긋납니다.",
};
const LEAK = {
  비겁:"사람 때문에 나갑니다. 빌려주고 못 받거나, 함께 벌여놓고 나눠 쓰는 자리가 많습니다. 정이 많아서가 아니라 구조가 그렇습니다.",
  식상:"벌여놓은 일 때문에 나갑니다. 아이디어가 많아 여러 개를 동시에 굴리다 어느 것도 회수 전에 다음으로 넘어갑니다.",
  재성:"규모 때문에 나갑니다. 들어오는 만큼 씀씀이가 같이 커져서, 수입이 두 배가 되어도 잔고는 그대로입니다.",
  관성:"체면과 책임 때문에 나갑니다. 맡은 자리를 지키느라 쓰는 돈, 남 보기에 필요한 돈이 계속 생깁니다.",
  인성:"배우고 갖추는 데 나갑니다. 자격증, 수업, 장비처럼 준비에 드는 비용이 실제 수익보다 앞서 나갑니다.",
};
const WEALTH_FIELD = {
  목:"사람을 키우고 가르치는 쪽, 교육과 콘텐츠, 생물과 식물을 다루는 일에서 돈이 붙습니다.",
  화:"드러내고 알리는 쪽, 마케팅과 방송, 뷰티와 IT, 에너지를 다루는 일에서 돈이 붙습니다.",
  토:"땅과 공간을 다루는 쪽, 부동산과 중개, 요식과 유통처럼 실물이 오가는 일에서 돈이 붙습니다.",
  금:"기준을 다루는 쪽, 금융과 법률, 제조와 정밀, 판단이 값이 되는 일에서 돈이 붙습니다.",
  수:"흐름을 다루는 쪽, 유통과 무역, 연구와 분석, 정보가 값이 되는 일에서 돈이 붙습니다.",
};
const ASSET_TYPE = {
  신강:"현금보다 실물이 맞습니다. 힘이 넉넉한 구조라 쥐고 버티는 자산, 부동산이나 지분처럼 시간이 값을 만드는 쪽에서 성과가 납니다.",
  중화:"어느 한쪽으로 몰지 않는 편이 낫습니다. 현금과 실물을 나눠 두고, 시기에 따라 비중을 옮기는 방식이 맞습니다.",
  신약:"실물보다 현금과 유동성이 맞습니다. 큰 것을 오래 쥐고 있으면 그 무게에 눌리니, 언제든 빠져나올 수 있는 형태로 두세요.",
};

/**
 * 재물사주 — 돈 하나만 서른 가지로 본다
 */
export function buildWealthReport(saju, opts = {}) {
  const st = analyzeStrength(saju);
  const me = saju.dayMaster.element;
  const roles = elementRoles(me);
  const stemKo = saju.dayMaster.stem;
  const dom = dominantSipsin(saju);
  const byEl = {}; saju.elements.forEach(e => byEl[e.name] = e.ratio);

  const jaeEl = CTL[me], sikEl = GEN[me], biEl = me;
  const jae = byEl[jaeEl], sik = byEl[sikEl], bi = byEl[biEl];
  const bowl = MONEY_BOWL.find(b => jae <= b.max);

  // 편재/정재 비중
  const jaeSpots = [];
  ["year","month","day","hour"].forEach(k => {
    const p = saju.pillars[k]; if (!p) return;
    if (GROUP.재성.includes(p.stemSipsin))   jaeSpots.push(p.stemSipsin);
    if (GROUP.재성.includes(p.branchSipsin)) jaeSpots.push(p.branchSipsin);
  });
  const pyeon = jaeSpots.filter(x => x === "편재").length;
  const jeong = jaeSpots.filter(x => x === "정재").length;
  const styleKey = !jaeSpots.length ? "없음" : pyeon && jeong ? "혼합" : pyeon ? "편재" : "정재";

  // 새는 구멍 = 가장 두터운 오행의 역할
  const heaviest = [...saju.elements].sort((a,b) => b.ratio - a.ratio)[0];
  const leakRole = roles[heaviest.name];

  const age = opts.currentAge ?? exactAge(saju);
  const ageShown = Math.floor(age);
  const nowDaeun = saju.daeun.list.find(d => age >= d.startAge && age < d.startAge + 10)
                 || saju.daeun.list[0];
  const pickAll = (names) => saju.daeun.list.filter(d => names.includes(d.sipsin) && d.startAge < 80);
  const aheadOnly = (arr) => arr.filter(d => d.startAge + 10 > age);
  const pick = (names) => {
    const all = pickAll(names);
    const ahead = aheadOnly(all);
    return ahead.length ? ahead : all;
  };
  const jaeDaeun = pick(GROUP.재성);
  const sikDaeun = pick(GROUP.식상);
  const gyeopDaeun = pick(["겁재"]);
  const peak = jaeDaeun.length ? jaeDaeun[0] : sikDaeun.length ? sikDaeun[0] : null;

  const dMark = (d) => d.startAge + 10 <= age ? " _(지나온 시기)_"
                     : d.startAge <= age ? " _(지금 이 구간)_" : "";
  const dList = (arr, empty) => arr.length
    ? arr.map(d => `**${Math.floor(d.startAge)}세 ~ ${Math.floor(d.startAge)+10}세 · ${d.gapjaCn}(${d.sipsin})**${dMark(d)} — ${DAEUN_NOTE[d.sipsin]}`).join("\n")
    : empty;

  const thisYear = new Date().getFullYear();
  const jaeYears   = goodYears(saju, GROUP.재성);
  const sikYears   = goodYears(saju, GROUP.식상);
  const gyeopYears = goodYears(saju, ["겁재"]);
  const goYears    = yongsinYears(saju);
  const badYears   = riskYears(saju);
  const yr = buildYearReport(saju, thisYear);
  const money = yr.fields.find(f => f.key === "money");
  const lk = LUCKY[st.yongsin];

  let n = 0;
  const q = (question, body, free = false) =>
    ({ no: ++n, question, body: [].concat(body).filter(x => typeof x === "string" && x.trim()), free });
  const S = (title, sub, items) => ({ title, sub, items });

  const sections = [
    S("내 돈 그릇", "얼마나 담기는 사람인가", [
      q("내 사주의 돈 그릇은 얼마나 큰가요?", [
        `당신에게 재성은 ${jaeEl}이고, 명식에서 ${jae}%를 차지합니다. ${bowl.t}입니다.`,
        bowl.b,
      ], true),
      q("나는 버는 사람인가요, 지키는 사람인가요?", [
        `식상(만드는 힘)이 ${sik}%, 재성(담는 그릇)이 ${jae}%입니다.`,
        sik > jae
          ? `만드는 힘이 담는 그릇보다 큽니다. 벌 줄은 아는데 남기는 구조가 약합니다. 버는 방법을 더 찾기보다 남기는 장치를 먼저 만드셔야 합니다.`
          : sik < jae
          ? `담는 그릇이 만드는 힘보다 큽니다. 기회는 보이는데 그것을 실제 수익으로 바꾸는 손이 부족합니다. 만들어내는 쪽에 시간을 더 쓰셔야 합니다.`
          : `만드는 힘과 담는 그릇이 비슷합니다. 벌면 버는 대로 남는 구조라, 규모를 키우는 것이 그대로 결과가 됩니다.`,
      ], true),
      q("내 돈은 어디서 들어오나요?", [
        `돈은 식상이 재성을 낳는 흐름을 탑니다. 당신의 경우 ${sikEl} → ${jaeEl}로 흐릅니다.`,
        WEALTH_FIELD[jaeEl],
        `${SIPSIN_TRAIT[dom]} 이 기질이 돈으로 바뀌는 지점을 찾는 것이 핵심입니다.`,
      ]),
      q("나는 월급이 맞나요, 사업이 맞나요?", [
        byEl[CTL_BY[me]] >= 22
          ? `관성이 ${byEl[CTL_BY[me]]}%로 받쳐줍니다. 조직 안에서 자리가 올라가며 버는 구조가 맞습니다. 사업은 조직에서 충분히 쌓은 뒤가 안전합니다.`
          : bi >= 30
          ? `비겁이 ${bi}%로 두텁고 관성이 얇습니다. 남 밑에서 오래 못 버티는 구조라 결국 자기 판을 만들게 됩니다. 문제는 시기입니다.`
          : `어느 한쪽으로 뚜렷하지 않습니다. 조직에 있되 본인 영역이 분명한 자리, 또는 소수 인원의 팀이 맞습니다.`,
      ]),
      q("내가 가진 돈 버는 재능은 무엇인가요?", [
        `${SIPSIN_TRAIT[dom]}`,
        sik >= 20
          ? `식상이 ${sik}%로 살아 있습니다. 만들고 표현하는 힘이 그대로 수익이 되는 구조라, 남의 판에서 월급만 받으면 능력이 다 안 쓰입니다.`
          : `식상이 ${sik}%로 얇습니다. 직접 만들어 파는 쪽보다 있는 판에 올라타 관리하고 굴리는 쪽이 맞습니다.`,
      ]),
      q("남들보다 유리한 분야가 있나요?", [
        WEALTH_FIELD[jaeEl],
        `여기에 용신 ${st.yongsin} 기운을 얹으면 더 오래갑니다. ${YONGSIN[st.yongsin].b}`,
      ]),
    ]),

    S("왜 안 모이나", "새는 구멍부터 막아야 합니다", [
      q("버는데 왜 안 모이나요?", [
        `가장 두터운 기운은 ${heaviest.name}(${leakRole}) ${heaviest.ratio}%입니다. 돈이 새는 통로가 여기입니다.`,
        LEAK[leakRole],
        jae <= 12 ? `게다가 재성이 ${jae}%로 얇아 담아두는 힘 자체가 약합니다.` : "",
        `**막는 법.** ${DRAIN[leakRole]}`,
        `구체적으로는 이렇습니다. 수입이 들어오는 날 바로 일정 비율을 다른 계좌로 옮겨 묶어두세요. 이 사주는 통장에 남아 있으면 ${leakRole} 쪽으로 빠져나갑니다. 의지로 막는 구조가 아니라 손이 닿지 않게 만드는 구조여야 합니다.`,
      ].filter(Boolean)),
      q("돈이 새는 구멍은 정확히 어디인가요?", [
        LEAK[leakRole],
        bi >= 30 ? `비겁이 ${bi}%입니다. 사람 사이 금전이 가장 큰 구멍입니다. 빌려주는 돈, 함께 벌이는 일의 지분, 밥값과 경조사가 여기 해당합니다.` : "",
        byEl[GEN_BY[me]] >= 30 ? `인성이 ${byEl[GEN_BY[me]]}%로 두텁습니다. 준비와 학습에 드는 비용이 실제 수익보다 앞서 나가는 구조입니다.` : "",
      ].filter(Boolean)),
      q("돈 앞에서 내가 반복하는 실수는 무엇인가요?", [
        MISTAKE[stemKo],
        `돈 문제로 옮겨 오면 이렇게 나타납니다. ${LEAK[leakRole]}`,
      ]),
      q("나를 가난하게 만드는 습관은 무엇인가요?", [
        st.level === "신강"
          ? `힘이 넘치는데 쓸 곳을 안 정하는 습관입니다. 넘치는 기운을 비우지 않으면 안에서 부딪혀 엉뚱한 곳에서 소모됩니다.`
          : `혼자 다 지려는 습관입니다. ${st.level} 구성이라 도움을 빌려야 멀리 가는데, 끝까지 혼자 해결하려다 바닥을 봅니다.`,
        `그리고 ${st.gisin}(${roles[st.gisin]})을 더 쌓으려는 습관입니다. 이미 충분한데 계속 더하는 자리라, 여기에 쓰는 돈과 시간이 가장 아깝습니다.`,
        `**바꾸는 법.** ${DRAIN[roles[st.gisin]]}`,
        `그리고 부족한 ${st.yongsin}을 채워야 합니다. ${FILL[st.yongsin].how[0]} ${FILL[st.yongsin].who}`,
      ]),
      q("돈 때문에 조심해야 할 사람은 누구인가요?", [
        bi >= 28
          ? `비겁이 두터워 또래와 동료 사이 금전이 가장 위험합니다. 보증, 대여, 지분 나눔이 전부 여기 해당합니다.`
          : `특정 유형이 크게 위험한 구조는 아닙니다. 다만 ${ROLE_MEANS[roles[st.gisin]].w} 쪽으로 계속 끌어당기는 사람은 거리를 두셔야 합니다.`,
        gyeopDaeun.length
          ? `겁재 대운인 ${gyeopDaeun.map(d => Math.floor(d.startAge) + "세").join(", ")} 구간에는 특히 조심하셔야 합니다.`
          : `겁재 대운은 오지 않으니 큰 사고 구간은 없는 편입니다.`,
      ]),
      q("빚을 내도 되는 사주인가요?", [
        st.level === "신약"
          ? `신약 구성이라 빚의 무게에 눌립니다. 감당 가능한 선이 남들보다 낮으니 레버리지보다 자기 자본으로 천천히 가는 쪽이 맞습니다.`
          : `신강 구성이라 어느 정도의 부담은 오히려 동력이 됩니다. 다만 규모를 먼저 정해두고 들어가야 합니다.`,
        jaeYears.length
          ? `**감당 범위가 넓어지는 해는 ${yearLine(jaeYears, 3)}입니다.** 재성이 들어오는 해라 회수가 빨라집니다. 반대로 ${badYears.length ? badYears.slice(0,2).map(x => x.year + "년").join(", ") + " 같은" : "기신이 두꺼워지는"} 해에 새로 빌리는 것은 피하세요.`
          : `앞으로 12년 안에 재성이 들어오는 해가 없습니다. 큰 레버리지는 권하지 않습니다.`,
        `**규모를 정하는 기준.** 월 상환액이 월 수입의 ${st.level === "신약" ? "25%" : "35%"}를 넘기지 않는 선입니다. 이 사주는 그 선을 넘으면 판단이 먼저 흐려집니다.`,
      ]),
    ]),

    S("언제 터지나", "시기를 알면 같은 돈도 달라집니다", [
      q("돈이 크게 들어오는 시기는 언제인가요?", [
        jaeYears.length
          ? `**가까운 해는 ${yearLine(jaeYears)}입니다.** 재성이 세운으로 들어오는 해라, 벌이의 폭이 커지고 큰 거래가 붙습니다.`
          : `앞으로 12년 안에 재성이 세운으로 들어오는 해는 없습니다. 한 방보다 구조로 가는 사주입니다.`,
        dList(jaeDaeun, "대운에 재성이 직접 들어오지는 않습니다. 10년 단위의 큰 파도보다 위의 해를 골라 쓰는 방식이 맞습니다."),
        `해가 좋아도 그 전 해에 아무것도 없으면 그냥 지나갑니다. 위 해의 **1년 전**이 준비할 때입니다.`,
      ]),
      q(`올해(${thisYear}년) 내 재물운은 어떤가요?`, [
        `${yr.gapjaCn}년입니다. ${yr.lead}`,
        `재물운은 ${money.score}점, ${money.grade}입니다. ${money.text}`,
      ]),
      q("향후 10년, 내 돈은 어떻게 흘러가나요?", [
        `지금은 만 ${ageShown}세, ${Math.floor(nowDaeun.startAge)}세에 시작한 ${nowDaeun.gapjaCn}(${nowDaeun.sipsin}) 대운 안입니다.`,
        `${DAEUN_NOTE[nowDaeun.sipsin]} ${SIPSIN_TRAIT[nowDaeun.sipsin]}`,
        `이 대운은 ${Math.floor(nowDaeun.startAge)+10}세까지 이어집니다. 지금의 벌이 구조는 개인의 노력보다 이 10년의 성격에서 나오는 부분이 큽니다.`,
        `**연도별 흐름.**\n` + goodYears(saju, null, { span: 10 })
            .map(y => `${y.year}년(만 ${y.age}세) ${y.gapjaCn} · ${y.sipsin} — ${DAEUN_NOTE[y.sipsin]}`).join("\n"),
        `표에서 ${GROUP.재성.join("·")}이 붙은 해가 벌이의 해, ${"겁재"}가 붙은 해가 지키는 해입니다.`,
      ]),
      q("몇 살에 가장 많이 버나요?", (() => {
        const out = [];
        if (peak) {
          const mark = peak.startAge + 10 <= age ? "이미 지나온 구간입니다" : peak.startAge <= age ? "지금 그 구간 안에 있습니다" : "앞으로 올 구간입니다";
          out.push(`${Math.floor(peak.startAge)}세 ~ ${Math.floor(peak.startAge)+10}세, ${peak.gapjaCn}(${peak.sipsin}) 대운이 가장 유력합니다. ${mark}.`);
          out.push(DAEUN_NOTE[peak.sipsin]);
        } else {
          out.push("재성과 식상이 직접 들어오는 대운이 없습니다. 한 번에 크게 버는 구조가 아니라 길게 쌓는 구조입니다.");
        }
        const ys = jaeYears.length ? jaeYears : sikYears;
        if (ys.length) out.push(`**연 단위로 보면 ${yearLine(ys, 3)}입니다.** 대운이 멀어도 이 해들은 바로 쓸 수 있습니다.`);
        out.push(`구간이 실제로 얼마나 커지는지는 그 전에 무엇을 쌓아뒀는지로 정해집니다. 황금기는 준비된 사람에게만 황금기입니다.`);
        return out;
      })()),
      q("사업을 시작한다면 언제가 좋을까요?", [
        sikYears.length
          ? `**${yearLine(sikYears, 3)}이 좋습니다.** 식상이 세운으로 들어오는 해라 만들어 내보내는 힘이 붙습니다.`
          : jaeYears.length
          ? `식상이 들어오는 해는 없고, 대신 재성이 들어오는 ${yearLine(jaeYears, 2)}가 낫습니다. 새로 만들기보다 있는 구조를 사거나 올라타는 방식입니다.`
          : `앞으로 12년 안에 시작을 받쳐주는 해가 뚜렷하지 않습니다. 전업보다 부업으로 한 줄 열어두고 1년을 보시는 편이 안전합니다.`,
        sikDaeun.length
          ? `10년 단위로는 ${sikDaeun.map(d => Math.floor(d.startAge)+"세 "+d.gapjaCn).join(", ")} 구간이 식상 대운입니다.`
          : `식상 대운은 오지 않습니다. 대운보다 위의 해를 기준으로 삼으세요.`,
        `대운이 바뀌는 앞뒤 1년은 판이 흔들리는 구간입니다. 개업은 그 흔들림이 지나간 뒤가 안전합니다.`,
      ]),
      q("투자해도 되는 시기는 언제인가요?", [
        `기준은 단순합니다. 용신 ${st.yongsin}이 들어오는 해에는 늘리고, 기신 ${st.gisin}이 두꺼워지는 해에는 지킵니다.`,
        goYears.length
          ? `**늘릴 해 — ${goYears.slice(0,4).map(x => `${x.year}년(만 ${x.age}세, ${x.gapjaCn})`).join(", ")}.** 용신이 세운으로 들어오는 해입니다.`
          : `앞으로 12년 안에 용신이 세운으로 들어오는 해가 없습니다. 크게 늘리는 판단은 미루는 쪽이 안전합니다.`,
        badYears.length
          ? `**지킬 해 — ${badYears.slice(0,4).map(x => `${x.year}년(${x.gapjaCn})`).join(", ")}.** 기신이 두꺼워지는 해라 판단이 흐려집니다. 이 해에는 신규 투자보다 현금 비중을 늘리세요.`
          : `기신이 세게 들어오는 해는 없습니다.`,
        jaeDaeun.length
          ? `10년 단위로는 ${jaeDaeun.map(d => Math.floor(d.startAge)+"세").join(", ")} 구간이 재성 대운입니다.`
          : `재성 대운이 없으니 위의 연 단위 기준으로 짧게 끊어 판단하셔야 합니다.`,
      ]),
      q("돈 사고가 나는 시기는 언제인가요?", [
        gyeopDaeun.length
          ? `겁재 대운인 ${gyeopDaeun.map(d => Math.floor(d.startAge)+"세 "+d.gapjaCn).join(", ")} 구간입니다. 경쟁과 지출이 함께 늘고, 사람 사이 금전에서 사고가 납니다.`
          : `겁재 대운은 오지 않습니다. 큰 사고 구간은 없는 편이나, 기신 ${st.gisin}이 겹치는 해에는 무리하지 않는 편이 좋습니다.`,
        gyeopYears.length
          ? `**연 단위로는 ${yearLine(gyeopYears, 3)}입니다.** 이 해에 들어오는 돈 얘기는 특히 걸러야 합니다.`
          : "",
        `**이 구간을 통과하는 법.** ${DAEUN_FIX["겁재"]}`,
        saju.gongmang.length ? `공망은 ${saju.gongmang.join("·")}입니다. 이 지지가 들어오는 해에 벌인 일은 손에 남지 않는 경우가 많습니다.` : "",
        `사고는 대부분 '좋아 보이는 제안'의 모습으로 옵니다. 위 구간에 들어온 제안은 하루 자고 결정하시고, 돈이 오가는 일은 반드시 문서로 남기세요. 이 두 가지만 지켜도 이 사주의 금전 사고는 거의 막힙니다.`,
      ].filter(Boolean)),
    ]),

    S("어떻게 버나", "구조를 바꿔야 액수가 바뀝니다", [
      q("나에게 맞는 돈 버는 구조는 무엇인가요?", (() => {
        const wm = workMode(saju), mf = modernFit(saju);
        const lines = [WEALTH_STYLE[styleKey], `${SIPSIN_TRAIT[dom]} 이 결을 그대로 수익 구조에 옮기면 무리가 없습니다.`];
        lines.push(`**어느 분야에서 벌 것인가.** 1순위는 ${mf.best.k}입니다. ${mf.best.why} 구체적으로는 ${mf.best.good} 쪽입니다.`);
        lines.push(`${mf.best.how} 그리고 ${mf.best.bad}`);
        lines.push(`2순위는 ${mf.second.k}입니다. ${mf.second.how} 비중은 1순위 7, 2순위 3 정도가 맞습니다.`);
        const jm = jobMatch(saju, opts.job);
        if (jm) { lines.push(`**지금 하시는 일은 ${jm.label}입니다.** ${jm.verdict}`); if (jm.bridge) lines.push(jm.bridge); }
        lines.push(`**혼자인가 함께인가.** ${wm.key}입니다. ${wm.b} ${wm.do[0]}`);
        lines.push(sik > jae
          ? `**순서가 중요합니다.** 식상 ${sik}%가 재성 ${jae}%보다 큽니다. 만드는 힘이 그릇보다 크다는 뜻이라, 더 만드는 쪽으로 가면 손에 남지 않습니다. 이미 만든 것 중 하나를 골라 파는 구조를 먼저 완성하세요. 그다음에 다음 것을 만드는 순서여야 합니다.`
          : `**순서가 중요합니다.** 재성 ${jae}%가 식상 ${sik}%보다 큽니다. 담을 준비는 됐는데 채울 것이 부족합니다. 새로 벌이기보다 지금 가진 것의 품질을 올리고 단가를 높이는 쪽이 같은 노력으로 더 큽니다.`);
        return lines;
      })()),
      q("동업해도 되나요? 한다면 누구와 해야 하나요?", [
        bi >= 30
          ? `비겁이 ${bi}%로 두터워 동업에 불리합니다. 지분과 역할을 문서로 못 박지 않으면 반드시 한 번 크게 부딪힙니다.`
          : `동업 자체가 막힌 구조는 아닙니다. 다만 결정권을 나누기보다 영역을 나누는 방식이 맞습니다.`,
        `함께하면 좋은 쪽은 ${HELPER[roles[st.yongsin]]}입니다. 당신에게 부족한 ${st.yongsin} 기운을 가진 사람입니다.`,
      ]),
      q("부동산인가요, 현금인가요?", [ASSET_TYPE[st.level]]),
      q("눈앞의 기회가 진짜인지 어떻게 구분하나요?", [
        `기준은 하나입니다. 그 기회가 ${st.yongsin}(${roles[st.yongsin]}) 쪽으로 가는지, ${st.gisin}(${roles[st.gisin]}) 쪽으로 가는지를 보시면 됩니다.`,
        `${ROLE_MEANS[roles[st.gisin]].w}을 더 쌓는 방향이면 반짝여도 빈손으로 끝납니다. 이미 충분한 자리를 더 채우는 일이기 때문입니다.`,
        `반대로 ${ROLE_MEANS[roles[st.yongsin]].w} 쪽으로 가는 기회는 작아 보여도 남습니다.`,
      ]),
      q("규모를 키워야 할 때와 지켜야 할 때는 언제인가요?", [
        `${st.level} 구성입니다. ${STRENGTH[st.level]}`,
        st.level === "신강"
          ? `밀어붙이는 국면에 강하니 키울 수 있을 때 확실히 키우는 편이 맞습니다. 다만 쓸 곳을 정하지 않으면 그 힘이 엉뚱한 데서 소모됩니다.`
          : `혼자 규모를 키우면 눌립니다. 사람과 구조를 먼저 갖춘 뒤에 늘리셔야 합니다.`,
      ]),
      q("나를 부자로 만드는 사람은 누구인가요?", [
        `당신에게 필요한 것은 ${st.yongsin}(${roles[st.yongsin]})입니다. 그 기운을 가진 사람이 곁에 있으면 같은 노력으로 더 멀리 갑니다.`,
        `구체적으로는 ${HELPER[roles[st.yongsin]]}입니다.`,
        Object.keys(saju.sinsal).includes("천을귀인")
          ? `명식에 천을귀인이 있습니다. 결정적인 순간에 도와주는 사람이 나타나는 자리입니다.`
          : `천을귀인은 없습니다. 도움은 저절로 오기보다 먼저 청해야 오는 편입니다.`,
      ]),
    ]),

    S("그래서 어떻게", "마지막으로 짚어드립니다", [
      q("내 인생 최고의 재물 시기는 언제인가요?",
        peak
          ? [`${Math.floor(peak.startAge)}세 ~ ${Math.floor(peak.startAge)+10}세, ${peak.gapjaCn}(${peak.sipsin}) 대운입니다.`,
             `${DAEUN_NOTE[peak.sipsin]}`,
             ageShown < peak.startAge
               ? `아직 오지 않았습니다. 남은 시간에 무엇을 쌓아두느냐가 그 구간의 크기를 정합니다.`
               : ageShown < peak.startAge + 10
               ? `지금 그 구간 안에 있습니다. 이 시기를 어떻게 쓰느냐가 이후 20년을 좌우합니다.`
               : `이미 지나왔습니다. 다만 사주의 시기는 한 번뿐인 기회가 아니라 파도의 높낮이입니다. 다음 파도를 준비하는 쪽이 맞습니다.`]
          : `한 구간에 몰린 시기는 없습니다. 크게 터지지 않는 대신 크게 꺼지지도 않는 구조라, 길게 쌓는 방식이 본인에게 맞습니다.`),
      q("돈 불안이 올라올 때는 어떻게 해야 하나요?", [
        `${st.level} 구성이라 ${st.level === "신강" ? "불안이 올라올 때 더 벌이려 움직이는" : "불안이 올라올 때 더 움츠러드는"} 쪽입니다. 둘 다 그 순간에는 도움이 안 됩니다.`,
        `당신에게 필요한 것은 ${st.yongsin}, ${YONGSIN[st.yongsin].k}입니다. ${YONGSIN[st.yongsin].b}`,
        `숫자를 들여다보는 것보다 구조를 한 줄로 적어보는 편이 빠릅니다. 들어오는 곳과 나가는 곳, 두 줄이면 충분합니다.`,
      ]),
      q("부자가 되려면 어떤 구조를 만들어야 하나요?", [
        WEALTH_STYLE[styleKey],
        sik > jae
          ? `만드는 힘이 그릇보다 크니, 남기는 장치를 먼저 만드세요. 버는 방법을 더 찾는 것은 그다음입니다.`
          : `그릇이 만드는 힘보다 크니, 만들어내는 쪽에 시간을 더 쓰세요. 담을 준비는 이미 되어 있습니다.`,
        ASSET_TYPE[st.level],
        (() => {
          const wm = workMode(saju), mf = modernFit(saju);
          return `**구조로 정리하면 이렇습니다.** ${mf.best.k}를 중심에 두고, ${wm.key === "독립형" ? "결정은 혼자 하되 실행은 나눠" : wm.key === "조직형" ? "외부에서 마감과 기준을 받아오는 형태로" : wm.key === "조력형" ? "간판은 넘기고 설계와 운영을 쥐는 형태로" : wm.key === "창작형" ? "만드는 나와 파는 사람을 짝지어" : "본인 영역이 분명한 소수 팀으로"} 가세요. 여기에 ${st.yongsin} 기운을 채우는 생활을 얹으면 같은 일을 해도 결과가 달라집니다.`;
        })(),
        `마지막으로, 레버리지를 하나 거세요. 자동화든 사람이든 녹화든, 내 시간이 들어가지 않아도 굴러가는 장치가 하나는 있어야 그릇이 실제로 찹니다. 시간을 파는 구조만으로는 어떤 사주도 크게 못 법니다.`,
      ]),
      q("나를 돕는 재물의 기운은 무엇인가요?", [
        `용신 ${st.yongsin}을 채우는 방향입니다.`,
        `색은 ${lk.color}, 방위는 ${lk.dir}, 숫자는 ${lk.num}, 시간대는 ${lk.time}입니다.`,
        `머물면 좋은 곳은 ${lk.place}입니다. 계약이나 중요한 결정은 이 조건을 맞춰 잡으시면 됩니다.`,
      ]),
      q("마지막으로, 돈에 대해 해주실 말씀이 있나요?", [
        ADVICE_ILGAN[stemKo],
        `${EUL(bowl.t)} 가지고 태어나셨습니다. 그릇의 크기는 바꿀 수 없지만, 새는 곳을 막고 담는 속도를 올리는 것은 할 수 있습니다.`,
        `사주에서 부자가 되는 사람과 안 되는 사람의 차이는 그릇이 아니라 구멍입니다. 당신의 구멍은 ${leakRole} 자리였습니다.`,
      ]),
    ]),
  ];

  const total = sections.reduce((a,s) => a + s.items.length, 0);
  const freeCount = sections.reduce((a,s) => a + s.items.filter(i => i.free).length, 0);

  return polish({
    title: `${saju.solar.year}년생 ${saju.dayMaster.stemCn}${stemKo}일간 재물사주`,
    summary: `${bowl.t}. 재성 ${jae}%, 식상 ${sik}%. 새는 곳은 ${leakRole} 자리입니다.`,
    hook: {
      lines: HOOK[stemKo],
      turn: [
        `돈 그릇은 있는 사주입니다.`,
        `그런데 새는 곳이 하나 있습니다.`,
        `버는 만큼 남지 않았던 이유가 여기 있습니다.`,
        `어디가 새고 있는지, 지금부터 짚어드리겠습니다.`,
      ],
    },
    stats: { bowl: bowl.t, jae, sik, bi, leak: leakRole, level: st.level, yongsin: st.yongsin },
    method: METHOD_NOTE,
    sections, total, freeCount,
  });
}


/**
 * 인연사주 — 30문항. 각 답변에 근거(evidence)와 처방(action)을 붙인다.
 */
export function buildDestinyReport(saju, opts = {}) {
  const st = analyzeStrength(saju);
  const me = saju.dayMaster.element;
  const meYin = saju.dayMaster.yinyang === "양" ? 0 : 1;
  const roles = elementRoles(me);
  const stemKo = saju.dayMaster.stem;
  const isMale = saju.input.gender === "M";
  const byEl = {}; saju.elements.forEach(e => byEl[e.name] = e.ratio);

  const L = buildLoveReport(saju, opts);
  const pEl = isMale ? CTL[me] : CTL_BY[me];
  const pNames = isMale ? GROUP.재성 : GROUP.관성;

  // 배우자성이 놓인 자리
  const spots = [];
  [["year","년주"],["month","월주"],["day","일주"],["hour","시주"]].forEach(([k,label]) => {
    const p = saju.pillars[k]; if (!p) return;
    if (pNames.includes(p.stemSipsin))   spots.push({ pos:label, where:"천간", sipsin:p.stemSipsin, cn:p.stemCn });
    if (pNames.includes(p.branchSipsin)) spots.push({ pos:label, where:"지지", sipsin:p.branchSipsin, cn:p.branchCn });
  });
  const placeKey = spots.length ? spots[0].pos : "없음";
  const palace = saju.pillars.day.branchSipsin;
  const palaceRole = ["비견","겁재"].includes(palace) ? "비겁"
                   : ["식신","상관"].includes(palace) ? "식상"
                   : ["편재","정재"].includes(palace) ? "재성"
                   : ["편관","정관"].includes(palace) ? "관성" : "인성";

  const age = opts.currentAge ?? exactAge(saju);
  const ageShown = Math.floor(age);
  const nowDaeun = saju.daeun.list.find(d => age >= d.startAge && age < d.startAge + 10)
                 || saju.daeun.list[0];
  const loveDaeun = saju.daeun.list.filter(d => pNames.includes(d.sipsin) && d.startAge < 70);
  const thisYear = new Date().getFullYear();
  const yr = buildYearReport(saju, thisYear);
  const loveField = yr.fields.find(f => f.key === "love");
  const verify = buildVerify(saju, opts);

  // 명식 근거 문자열
  const evSpots = spots.length
    ? spots.map(s => `${s.pos} ${s.where}의 ${s.cn}(${s.sipsin})`).join(", ")
    : "명식에 드러난 배우자성 없음";
  const evBase = `일간 ${saju.dayMaster.stemCn}(${me}) 기준 ${isMale ? "재성" : "관성"}은 ${pEl}. ${evSpots}. 배우자궁은 일지 ${saju.pillars.day.branchCn}(${palace}).`;

  let n = 0;
  const q = (question, body, ev, act, free = false) =>
    ({ no: ++n, question, body: [].concat(body).filter(x => typeof x === "string" && x.trim()),
       evidence: ev || null, action: act || null, free });
  const S = (title, sub, items) => ({ title, sub, items });

  const sections = [
    S("사랑할 때의 나", "상대를 보기 전에 나부터", [
      q("나는 사랑할 때 어떤 사람인가요?",
        [LOVE_STYLE[stemKo],
         SEASON_MOD[saju.pillars.month.branch],
         `${st.level} 구성입니다. ${st.level === "신약" ? "상대의 영향을 크게 받는 쪽이라, 누구를 만나느냐가 삶의 방향을 거의 결정합니다." : "스스로 끌고 가는 힘이 있어, 기대기보다 함께 걷는 상대를 만날 때 오래갑니다."}`,
         DOM_MOD[dominantSipsin(saju)]],
        `일간 ${saju.dayMaster.stemCn}${stemKo}, ${st.level}(일간을 돕는 기운 ${st.support}%).`,
        LOVE_ACTION[stemKo], true),

      q("내가 연애에서 반복하는 패턴은 무엇인가요?",
        [LOVE_PATTERN[palaceRole],
         SPOUSE_PALACE[palace]],
        `배우자궁인 일지 ${saju.pillars.day.branchCn}에 ${palace}이 앉음.`,
        null, true),

      q("나는 표현하는 사람인가요, 참는 사람인가요?",
        [byEl[GEN[me]] >= 22
          ? `식상이 ${byEl[GEN[me]]}%로 살아 있습니다. 표현하는 쪽입니다. 좋고 싫음이 드러나 상대가 읽기 편한 대신, 말이 앞서 상처를 남기는 일이 있습니다.`
          : `식상이 ${byEl[GEN[me]]}%로 얇습니다. 참는 쪽입니다. 속에는 충분히 있는데 밖으로 나오는 데 시간이 걸려, 상대가 마음을 의심하는 일이 생깁니다.`,
         `이건 성격이 아니라 구조입니다. 고치려 애쓰기보다 방식을 바꾸는 편이 빠릅니다.`],
        `식상(${GEN[me]}) ${byEl[GEN[me]]}%.`,
        byEl[GEN[me]] >= 22
          ? "말하고 나서 후회하는 일이 반복되면, 중요한 말은 하루 자고 하세요."
          : "표현을 늘리려 애쓰지 말고 정해진 시간을 만드세요. 매주 한 번이면 충분합니다."),

      q("내 연애의 유통기한이 늘 비슷한 이유가 있나요?",
        [`관계가 끝나는 지점은 대개 같은 자리에서 반복됩니다. 당신의 경우 ${palaceRole} 자리입니다.`,
         `앞에서 본 패턴이 관계 초반에 작동한다면, 끝나는 국면에서는 ${TIRING[palaceRole]}`,
         `기간이 비슷하다면 상대가 바뀌어도 구조가 그대로였다는 뜻입니다. 사람을 바꾸는 것보다 이 지점 하나를 바꾸는 쪽이 결과를 크게 바꿉니다.`,
         `**끊는 지점은 하나입니다.** ${LOVE_ACTION[stemKo]} 관계가 늘 끝나던 그 시기가 오면, 평소와 다른 선택을 한 번만 해보세요. 그 한 번이 기간을 바꿉니다.`],
        `일지 ${palace}, 그리고 가장 두터운 기운 ${[...saju.elements].sort((a,b)=>b.ratio-a.ratio)[0].name}.`,
        "지난 연애 세 번의 '끝난 이유'를 한 줄씩 적어보세요. 같은 단어가 나오면 그게 당신의 자리입니다."),

      q("사람들은 나를 어떻게 보고 다가오나요?",
        [`바깥에서 보이는 얼굴은 년주와 월주에 드러납니다. 당신은 ${saju.pillars.month.stemSipsin}의 인상으로 읽힙니다.`,
         SIPSIN_TRAIT[saju.pillars.month.stemSipsin],
         `실제 속마음은 일주에 있습니다. 겉과 속의 거리가 있는 편이라면 상대가 알아가는 데 시간이 걸립니다.`],
        `월간 ${saju.pillars.month.stemCn}(${saju.pillars.month.stemSipsin}), 일지 ${saju.pillars.day.branchCn}(${palace}).`,
        null),

      q("나는 왜 그런 사람에게 끌릴까요?",
        [`사람은 대개 자기에게 없는 기운에 끌립니다. 당신에게 가장 얇은 것은 ${[...saju.elements].sort((a,b)=>a.ratio-b.ratio)[0].name}(${roles[[...saju.elements].sort((a,b)=>a.ratio-b.ratio)[0].name]})입니다.`,
         `그 기운을 가진 사람이 눈에 들어옵니다. 끌림 자체는 정확한 신호인데, 끌림만으로 고르면 나를 눌러버리는 사람까지 함께 들어옵니다.`,
         `필요한 것은 ${st.yongsin}(${roles[st.yongsin]})입니다. 끌림과 필요가 겹치는 사람이 가장 좋은 인연입니다.`],
        `가장 얇은 오행 ${[...saju.elements].sort((a,b)=>a.ratio-b.ratio)[0].name} ${[...saju.elements].sort((a,b)=>a.ratio-b.ratio)[0].ratio}%, 용신 ${st.yongsin}.`,
        null),
    ]),

    S("내 인연은 누구인가", "명식이 가리키는 사람", [
      q("내 배우자는 어떤 성격의 사람인가요?",
        [`${isMale ? "남자에게 배우자는 재성" : "여자에게 배우자는 관성"}으로 봅니다. 당신에게 그 자리는 ${pEl}입니다.`,
         L.partner.character],
        evBase, null),

      q("어떤 인상과 분위기의 사람인가요?",
        [L.partner.look,
         `다만 인상은 명식이 가장 약하게 짚는 부분입니다. 성격과 시기는 꽤 정확하게 나오지만, 외모는 참고 정도로 보시는 편이 맞습니다.`],
        `배우자성 오행 ${pEl}.`, null),

      q("어떤 일을 하는 사람인가요?",
        [`${L.partner.job} 쪽입니다.`,
         `업종 자체보다 그 일이 요구하는 기질이 맞는지를 보는 편이 정확합니다.`],
        `배우자성 오행 ${pEl}의 직업군.`, null),

      q("나이 차는 어떻게 되나요?",
        [L.partner.ageGap],
        `배우자성이 놓인 자리: ${evSpots}.`, null),

      q("어디서 만나게 되나요?",
        [MEET_PLACE[placeKey],
         placeKey === "없음"
           ? `이 경우는 가만히 기다리는 방식이 가장 불리합니다. 새로운 자리에 나가는 횟수가 그대로 확률이 됩니다.`
           : `이 자리가 가리키는 곳에서 만날 가능성이 높다는 뜻이지, 다른 곳에서 못 만난다는 뜻은 아닙니다.`],
        `배우자성 최초 위치: ${placeKey}.`,
        placeKey === "없음" ? "한 달에 한 번은 처음 가보는 모임에 나가세요. 이 사주는 움직인 만큼 만납니다." : null),

      q("내 인연은 몇 번 오나요?",
        [L.partner.countText],
        `배우자성 개수: ${spots.length}개.`, null),

      q("지금 옆에 있는 사람이 그 사람인가요?",
        [`명식으로는 특정 인물을 지목할 수 없습니다. 이건 한계를 분명히 말씀드리는 편이 맞습니다.`,
         `대신 확인할 수 있는 것은 두 가지입니다. 하나는 그 사람을 만난 해가 인연이 열리는 해였는지, 다른 하나는 그 사람이 당신에게 부족한 ${st.yongsin} 기운을 가졌는지입니다.`,
         `두 가지가 다 맞으면 명식이 가리키는 방향과 일치합니다. 한 가지만 맞아도 나쁘지 않습니다. 둘 다 아니라면 관계가 유지되는 이유가 인연보다 습관 쪽일 수 있습니다.`],
        `용신 ${st.yongsin}, 인연이 열리는 해: ${L.years.map(y=>y.year).join(", ")}.`,
        "상대의 생년월일을 알면 궁합에서 이 두 가지를 바로 확인할 수 있습니다."),
    ]),

    S("언제 오나", "시기를 알면 기다림이 달라집니다", [
      q("인연이 들어오는 해는 언제인가요?",
        [`만 ${L.nowAge}세 기준으로 봅니다. ${L.stage.note}`,
         L.pastYears.length
           ? `**이미 지나온 해**\n` + L.pastYears.map(y =>
               `${y.year}년 ${y.gapjaCn} · 만 ${y.age}세 (${y.phase}) — ${y.reasons.join(", ")}`).join("\n")
           : `만 18세 이후로 인연이 크게 열렸던 해는 없었습니다. 만남의 수 자체가 적은 구조입니다.`,
         L.pastYears.length
           ? `이 해들 중에 실제로 사람을 만났거나 관계가 크게 바뀐 해가 있었다면, 아래 앞으로의 해도 같은 방식으로 작동합니다.`
           : ``,
         `**앞으로 열리는 해**\n` + L.years.map(y =>
           `${y.year}년 ${y.gapjaCn} · 만 ${y.age}세 (${y.phase}) — ${y.reasons.join(", ")}`).join("\n"),
        ].filter(Boolean),
        `세운이 배우자성이거나, 배우자궁 ${saju.pillars.day.branchCn}과 육합·삼합을 이루는 해. 만 18세부터 앞으로 15년까지 전 구간을 훑음.`,
        "앞으로의 해 중 가장 가까운 해에는 사람을 만나는 자리를 평소보다 늘려보세요."),

      q("결혼 적기는 언제인가요?",
        loveDaeun.length
          ? loveDaeun.map(d => `**${Math.floor(d.startAge)}세 ~ ${Math.floor(d.startAge)+10}세 · ${d.gapjaCn}(${d.sipsin})** — 배우자성이 10년 내내 작동하는 구간입니다.`)
          : [`70세 이전 대운에 배우자성이 직접 들어오지 않습니다. 대운보다 세운에서 오는 해를 노리는 편이 맞습니다.`,
             `이런 구조는 결혼이 늦거나, 시기를 스스로 정해서 가는 경우가 많습니다.`],
        `대운 중 ${isMale ? "재성" : "관성"} 구간.`, null),

      q(`올해(${thisYear}년) 내 애정운은 어떤가요?`,
        [`${yr.gapjaCn}년입니다. ${yr.lead}`,
         `애정운은 ${loveField.score}점, ${loveField.grade}입니다. ${loveField.text}`],
        `${yr.gapjaCn}년 세운과 일간의 관계.`, null),

      q("늦은 인연인가요, 이른 인연인가요?",
        [placeKey === "년주" || placeKey === "월주"
          ? `배우자성이 앞쪽 기둥에 있습니다. 비교적 이른 인연 구조입니다. 이미 지나온 사람 중에 있었을 가능성도 있습니다.`
          : placeKey === "시주"
          ? `배우자성이 시주에 있습니다. 늦게 열리는 구조라 서둘러 정하면 어긋납니다.`
          : placeKey === "일주"
          ? `배우자성이 일주에 있습니다. 가장 가까운 자리라, 이미 알고 지내던 사람이 어느 날 다르게 보이는 방식으로 옵니다.`
          : `배우자성이 드러나 있지 않습니다. 시기가 정해져 있지 않다는 뜻이고, 움직인 만큼 앞당겨집니다.`,
         `늦다는 것이 나쁘다는 뜻은 아닙니다. 늦게 오는 인연이 오래 가는 구조도 있습니다.`],
        `배우자성 위치: ${placeKey}.`, null),

      q("헤어짐이 오는 시기도 있나요?",
        [`배우자궁 ${saju.pillars.day.branchCn}을 충하는 해에는 관계가 흔들립니다. 그 지지는 ${RJI_CN[RJI.indexOf(CHUNG[saju.pillars.day.branch])]}(${CHUNG[saju.pillars.day.branch]})입니다.`,
         `충이 온다고 반드시 헤어지는 것은 아닙니다. 마음이 들썩이고 결정을 서두르게 되는 시기라는 뜻이고, 그때 내린 결정이 나중에 후회로 남는 경우가 많습니다.`,
         saju.gongmang.length ? `공망인 ${saju.gongmang.join("·")} 해에도 관계가 붕 뜹니다.` : ""].filter(Boolean),
        `일지 ${saju.pillars.day.branchCn}의 충: ${RJI_CN[RJI.indexOf(CHUNG[saju.pillars.day.branch])]}, 공망: ${saju.gongmang.join("·")}.`,
        "충이 오는 해에는 이별과 결혼 어느 쪽도 그 해 안에 결정하지 마세요. 한 해만 넘기면 판단이 달라집니다."),

      q("지금은 기다릴 때인가요, 움직일 때인가요?",
        [`만 ${ageShown}세, ${Math.floor(nowDaeun.startAge)}세에 시작한 ${nowDaeun.gapjaCn}(${nowDaeun.sipsin}) 대운 안입니다.`,
         pNames.includes(nowDaeun.sipsin)
           ? `배우자성 대운 안에 있습니다. 움직일 때입니다. 이 구간에 만난 사람은 관계로 이어질 가능성이 높습니다.`
           : `배우자성 대운은 아닙니다. 지금은 사람을 찾기보다 본인 자리를 만드는 쪽에 시간을 쓰는 편이 결과적으로 빠릅니다.`,
         `${DAEUN_NOTE[nowDaeun.sipsin]}`],
        `현재 대운 ${nowDaeun.gapjaCn}(${nowDaeun.sipsin}).`, null),
    ]),

    S("무엇을 조심하나", "같은 자리에서 반복하지 않으려면", [
      q("내가 조심해야 할 상대는 어떤 사람인가요?",
        [`이미 넘치는 ${st.gisin}(${roles[st.gisin]}) 기운을 더 얹어주는 사람입니다.`,
         `${ROLE_MEANS[roles[st.gisin]].w} 쪽으로 계속 끌어당기는 관계가 그렇습니다. 나쁜 사람이라는 뜻이 아니라, 당신에게는 과한 자리라는 뜻입니다.`,
         `보통 그런 사람에게 가장 편안함을 느낍니다. 익숙한 것과 좋은 것은 다릅니다.`,
         `**그렇다고 피하기만 할 일은 아닙니다.** 이런 상대를 만나더라도 ${DRAIN[roles[st.gisin]]} 이 통로를 관계 밖에 따로 만들어두면 같은 사람과도 다르게 지낼 수 있습니다.`],
        `기신 ${st.gisin}(${roles[st.gisin]}).`, null),

      q("나를 지치게 하는 관계의 유형은 무엇인가요?",
        [TIRING[palaceRole],
         st.level === "신약"
           ? `신약 구성이라 관계에서 에너지를 빌려 씁니다. 받는 것 없이 주기만 하는 관계에서는 남들보다 빨리 바닥이 납니다.`
           : `신강 구성이라 관계에서도 주도하려 합니다. 상대가 계속 맞춰주는 관계는 편하지만, 그만큼 상대가 먼저 지칩니다.`],
        `일지 ${palace}, ${st.level}.`, null),

      q("내가 자꾸 좋은 사람을 놓치는 이유가 있나요?",
        [LOVE_MISS[stemKo],
         `놓치는 것은 상대를 못 알아봐서가 아니라, 알아본 뒤에 하는 행동이 늘 같기 때문입니다.`],
        `일간 ${saju.dayMaster.stemCn}${stemKo}의 고유 패턴.`,
        null),

      q("이별 후에 내가 오래 앓는 이유는 무엇인가요?",
        [byEl[GEN_BY[me]] >= 25
          ? `인성이 ${byEl[GEN_BY[me]]}%로 두텁습니다. 생각이 길어 한 사람을 오래 곱씹습니다. 잊으려 할수록 더 선명해지는 구조입니다.`
          : byEl[GEN[me]] <= 14
          ? `식상이 ${byEl[GEN[me]]}%로 얇습니다. 감정을 밖으로 못 꺼내 안에서 돕니다. 말하거나 쓰지 않으면 잘 안 빠집니다.`
          : `특별히 오래 앓는 구조는 아닙니다. 시간이 지나면 자연스럽게 정리되는 편입니다.`,
         `앓는 기간이 긴 것은 마음이 깊어서가 아니라 처리 방식 때문입니다. 방식만 바꾸면 기간이 줄어듭니다.`,
         `**줄이는 법.** ${FILL[st.yongsin].how[0]} 이별 직후일수록 ${st.yongsin} 기운 쪽으로 생활을 기울이면 회복이 눈에 띄게 빨라집니다.`],
        `인성(${GEN_BY[me]}) ${byEl[GEN_BY[me]]}%, 식상(${GEN[me]}) ${byEl[GEN[me]]}%.`,
        byEl[GEN[me]] <= 14 ? "그 사람에게 하고 싶었던 말을 부치지 않을 편지로 한 번 다 쓰세요. 꺼내는 행위 자체가 처리입니다." : null),

      q("재회해도 되는 사람인가요?",
        [`명식으로 특정 인물의 재회를 판단할 수는 없습니다. 이것도 한계를 말씀드리는 편이 맞습니다.`,
         `다만 기준은 드릴 수 있습니다. 헤어진 해가 배우자궁을 충하는 해였다면, 그때의 결정은 상황에 떠밀린 것일 가능성이 있습니다.`,
         `반대로 충이 아닌 해에 헤어졌다면 이유가 관계 안에 있었다는 뜻이고, 같은 이유가 다시 돌아옵니다.`],
        `일지 ${saju.pillars.day.branchCn}의 충: ${RJI_CN[RJI.indexOf(CHUNG[saju.pillars.day.branch])]}년.`, null),

      q("결혼 후에 부딪히는 지점은 어디인가요?",
        [AFTER_MARRY[palace]],
        `배우자궁 ${saju.pillars.day.branchCn}(${palace}).`, null),
    ]),

    S("어떻게 사랑하나", "바꿀 수 있는 것만 말씀드립니다", [
      q("나는 어떻게 사랑해야 하나요?",
        [`당신이 사랑하는 방식은 이미 정해져 있습니다. 고치라는 말씀을 드리려는 것이 아닙니다.`,
         LOVE_WAY[stemKo]],
        `일간 ${saju.dayMaster.stemCn}${stemKo}.`,
        null),

      q("나를 살리는 사람은 어떤 사람인가요?",
        [`당신에게 필요한 것은 ${st.yongsin}(${roles[st.yongsin]})입니다. 그 기운을 가진 사람 곁에서 같은 노력으로 더 멀리 갑니다.`,
         `구체적으로는 ${HELPER[roles[st.yongsin]]}입니다.`,
         Object.keys(saju.sinsal).includes("천을귀인")
           ? `명식에 천을귀인이 있습니다. 결정적인 순간에 도와주는 사람이 나타나는 자리입니다.`
           : `천을귀인은 없습니다. 도움은 저절로 오기보다 먼저 청해야 오는 편입니다.`],
        `용신 ${st.yongsin}(${roles[st.yongsin]}).`, null),

      q("좋은 인연을 부르는 방법이 있나요?",
        [`부적이나 주문 같은 것은 말씀드리지 않겠습니다. 명리가 말할 수 있는 것은 방향뿐입니다.`,
         `당신에게 필요한 ${st.yongsin} 기운 쪽으로 생활을 기울이면 만나는 사람의 결이 달라집니다. ${YONGSIN[st.yongsin].b}`,
         placeKey === "없음"
           ? `만나는 자리가 정해져 있지 않으니, 나가는 횟수가 그대로 확률이 됩니다.`
           : `${placeKey}가 가리키는 자리에 머무는 시간을 늘리는 것이 가장 직접적인 방법입니다.`],
        `용신 ${st.yongsin}, 배우자성 위치 ${placeKey}.`,
        `${LUCKY[st.yongsin].place}에서 시간을 늘려보세요. 사람은 자기가 머무는 곳의 기운을 닮은 사람을 만납니다.`),

      q("혼자인 시기를 어떻게 보내야 하나요?",
        [pNames.includes(nowDaeun.sipsin)
          ? `지금은 배우자성 대운 안이라 혼자인 시기가 길지 않을 구조입니다. 조급해하지 않으셔도 됩니다.`
          : `지금은 배우자성이 들어오는 구간이 아닙니다. 이 시기에 사람을 찾는 데 힘을 다 쓰면 정작 열리는 해에 쓸 힘이 없습니다.`,
         `혼자인 시기는 비어 있는 시간이 아니라 ${st.yongsin}을 채우는 시간입니다. ${YONGSIN[st.yongsin].b}`,
         `인연이 열리는 해에 준비된 사람과 그렇지 않은 사람의 결과는 크게 다릅니다.`],
        `현재 대운 ${nowDaeun.sipsin}, 다음 인연 해 ${L.years.length ? L.years[0].year : "미정"}.`, null),

      q("마지막으로, 저에게 해주실 말씀이 있나요?",
        [ADVICE_ILGAN[stemKo],
         L.tip,
         `사주는 누구를 만날지 정해주지 않습니다. 다만 당신이 어떤 사람에게 끌리고, 어디서 늘 같은 실수를 하고, 언제 문이 열리는지는 말해줍니다.`,
         `이 풀이에서 한 가지만 가져가신다면, ${LOVE_ACTION[stemKo]}`],
        null, null),
    ]),
  ];

  const total = sections.reduce((a,s) => a + s.items.length, 0);
  const freeCount = sections.reduce((a,s) => a + s.items.filter(i => i.free).length, 0);

  return polish({
    title: `${saju.solar.year}년생 ${saju.dayMaster.stemCn}${stemKo}일간 인연사주`,
    summary: `배우자성은 ${pEl}, 명식에 ${spots.length}개. 배우자궁은 ${saju.pillars.day.branchCn}(${palace}).`,
    verify,
    hook: {
      lines: HOOK[stemKo],
      turn: [
        `당신에게 인연이 없는 것이 아닙니다.`,
        `다만 같은 자리에서 매번 걸립니다.`,
        `상대가 바뀌어도 끝나는 이유가 비슷했을 겁니다.`,
        `그 자리가 어디인지, 지금부터 짚어드리겠습니다.`,
      ],
    },
    stats: {
      partnerEl: pEl, count: spots.length, palace, palaceCn: saju.pillars.day.branchCn,
      place: placeKey, level: st.level, yongsin: st.yongsin,
      nextYear: L.years.length ? L.years[0].year : null,
      nowAge: L.nowAge, stage: L.stage.key, pastCount: L.pastYears.length,
    },
    method: METHOD_NOTE,
    disclaimer: "외모나 직업처럼 명식이 약하게 짚는 항목은 참고로만 보시는 편이 맞습니다. 성격과 시기는 비교적 또렷하게 나옵니다.",
    sections, total, freeCount,
  });
}

/* ═══ 연도별 운세 ═══════════════════════════════════ */
const GRADE = (s) => s >= 78 ? "대길" : s >= 62 ? "길" : s >= 45 ? "평" : "주의";

export function buildYearReport(saju, year, opts = {}) {
  const st = analyzeStrength(saju);
  const me = saju.dayMaster.element;
  const meYin = saju.dayMaster.yinyang === "양" ? 0 : 1;
  const roles = elementRoles(me);
  const isMale = saju.input.gender === "M";

  const si = ((year - 4) % 10 + 10) % 10, bi = ((year - 4) % 12 + 12) % 12;
  const ys = RGAN[si], yb = RJI[bi];
  const ysCn = RGAN_CN[si], ybCn = RJI_CN[bi];
  const stemSipsin   = sipsinOf(me, meYin, RGAN_EL[ys], RGAN_YIN[ys]);
  const branchSipsin = sipsinOf(me, meYin, RJI_EL[yb],  RJI_YIN[yb]);
  const yearEls = [RGAN_EL[ys], RJI_EL[yb]];

  const age = opts.currentAge ?? (year - saju.solar.year);
  const dae = saju.daeun.list.find(d => age >= d.startAge && age < d.startAge + 10)
            || saju.daeun.list[0];
  const ageNow = Math.floor(exactAge(saju));

  const samjae = samjaeOf(saju.pillars.year.branch, yb);

  const TARGET = {
    total:null,
    money: GROUP.재성,
    love:  isMale ? GROUP.재성 : GROUP.관성,
    health:st.level === "신강" ? [...GROUP.식상, ...GROUP.재성] : [...GROUP.인성, ...GROUP.비겁],
    work:  GROUP.관성,
    study: GROUP.인성,
    doc:   GROUP.인성,
    people:[...GROUP.비겁, ...GROUP.식상],
    fame:  ["정관","정재"],
    move:  [...GROUP.재성, ...GROUP.관성],
    life:  st.level === "신강" ? [...GROUP.식상, ...GROUP.재성] : [...GROUP.인성, ...GROUP.비겁],
  };

  const scoreOf = (key) => {
    let s = 50;
    const t = TARGET[key];
    if (t) {
      if (t.includes(stemSipsin))   s += 18;
      if (t.includes(branchSipsin)) s += 14;
      if (t.includes(dae.sipsin))   s += 8;
    }
    if (yearEls.includes(st.yongsin)) s += 14;
    if (yearEls.includes(st.gisin))   s -= 13;
    if (samjae.on) s -= (samjae.stage === "눌삼재" ? 9 : 5);
    if (key === "love"   && saju.sinsal["도화"])          s += 7;
    if (key === "work"   && dae.sipsin === "편관")        s -= 5;
    if (key === "money"  && dae.sipsin === "겁재")        s -= 8;
    if (key === "doc"    && saju.gongmang.includes(yb))   s -= 8;
    if (key === "move"   && saju.sinsal["역마"])          s += 8;
    if (key === "people" && saju.sinsal["천을귀인"])      s += 6;
    if (key === "study"  && saju.sinsal["화개"])          s += 6;
    if (key === "health" && samjae.on)                    s -= 4;
    if (key === "health" && ["편관","상관"].includes(stemSipsin))   s -= 7;
    if (key === "health" && ["편관","상관"].includes(branchSipsin)) s -= 5;
    if (key === "health" && saju.sinsal["양인"])          s -= 4;
    if (key === "life"   && ["식신","정인","정재"].includes(stemSipsin)) s += 6;
    if (key === "life"   && saju.sinsal["천을귀인"])      s += 5;
    if (key === "life"   && samjae.stage === "눌삼재")    s -= 4;
    return Math.max(8, Math.min(95, Math.round(s)));
  };

  const rawTotal = Math.round(
    ["money","love","health","work","study","doc","people","fame","move","life"]
      .reduce((a,k) => a + scoreOf(k), 0) / 10);

  const EXTRA = {
    total:  `${ysCn}${ybCn}년의 기운은 ${RGAN_EL[ys]}와 ${RJI_EL[yb]}입니다.`,
    money:  `재물은 재성이 맡습니다. 당신에게 재성은 ${CTL[me]}이고 올해 들어오는 기운은 ${yearEls.join("·")}입니다.`,
    love:   `${isMale ? "남자에게 인연은 재성" : "여자에게 인연은 관성"}으로 봅니다. 당신에게 그 자리는 ${isMale ? CTL[me] : CTL_BY[me]}입니다.`,
    health: `${st.level} 구성이라 ${st.level === "신강" ? "덜어내는" : "채워주는"} 기운이 들어올 때 편안해집니다. 올해는 ${yearEls.includes(st.yongsin) ? "그 기운이 닿습니다" : "직접 닿지 않습니다"}.`,
    work:   `직업과 자리는 관성이 맡습니다. 당신에게 관성은 ${CTL_BY[me]}이고, 올해 지지로 들어오는 ${branchSipsin}이 실제 환경을 만듭니다.`,
    study:  `배움은 인성이 맡습니다. 당신에게 인성은 ${GEN_BY[me]}이며 올해 ${yearEls.includes(GEN_BY[me]) ? "그 기운이 직접 들어옵니다" : "직접 들어오지는 않습니다"}.`,
    doc:    `문서도 인성이 맡습니다. ${saju.gongmang.includes(yb) ? `올해 지지 ${ybCn}이 공망에 걸려 서류가 한 번 어긋날 수 있습니다.` : "올해 지지는 공망에 걸리지 않습니다."}`,
    people: `사람은 비겁과 식상으로 봅니다. 올해 천간은 ${stemSipsin}, 지지는 ${branchSipsin}입니다.`,
    fame:   `이름은 관성, 실리는 재성이 함께 움직일 때 붙습니다. 올해 천간은 ${stemSipsin}입니다.`,
    move:   `이동은 재성과 관성, 그리고 역마가 함께 봅니다. ${saju.sinsal["역마"] ? "명식에 역마가 있어 움직임이 잦은 편입니다." : "명식에 역마가 없어 이동이 잦은 구조는 아닙니다."}`,
    life:   `마음의 만족은 일간이 편안한지로 봅니다. 올해 기운은 ${yearEls.join("·")}입니다.`,
  };

  const fields = FIELDS.map(f => {
    const score = f.key === "total" ? rawTotal : scoreOf(f.key);
    const grade = GRADE(score);
    return { ...f, score, grade, text:FIELD_TEXT[f.key][grade], extra:EXTRA[f.key] };
  });

  // 월별 — 절기월 기준, 인월(2월)부터
  const JEOL12 = ["입춘","경칩","청명","입하","망종","소서","입추","백로","한로","입동","대설","소한"];
  const base = (si % 5) * 2 + 2;
  const months = Array.from({ length:12 }, (_, k) => {
    const mb = RJI[(2+k) % 12], mbCn = RJI_CN[(2+k) % 12];
    const mIdx = (base + k) % 10, ms = RGAN[mIdx];
    const ss = sipsinOf(me, meYin, RGAN_EL[ms], RGAN_YIN[ms]);
    const bs = sipsinOf(me, meYin, RJI_EL[mb],  RJI_YIN[mb]);
    const els = [RGAN_EL[ms], RJI_EL[mb]];
    let s = 50;
    if (els.includes(st.yongsin)) s += 18;
    if (els.includes(st.gisin))   s -= 15;
    if (saju.gongmang.includes(mb)) s -= 10;
    if (mb === yb) s -= 4;
    s = Math.max(10, Math.min(95, s));
    const grade = GRADE(s);
    const tail = saju.gongmang.includes(mb)
      ? " 공망에 걸린 달이라 애쓴 만큼 손에 남지 않을 수 있으니, 큰 결정은 앞뒤 달로 옮기세요."
      : els.includes(st.yongsin)
      ? ` 용신 ${st.yongsin}이 닿는 달이라 이 해에서 가장 힘이 실립니다. 중요한 일을 이 달에 배치하세요.`
      : els.includes(st.gisin)
      ? ` 기신 ${st.gisin}이 겹치는 달이라 무리하면 그대로 돌아옵니다. 속도를 줄이세요.`
      : "";
    return {
      label: `${((k+1) % 12) + 1}월`,
      jeol: JEOL12[k],
      gapjaCn: RGAN_CN[mIdx] + mbCn,
      sipsin: ss, branchSipsin: bs, score: s, grade,
      text: `${MONTH_OPEN[grade]} ${MONTH_BODY[ss]}${tail}`,
    };
  });

  const best  = [...months].sort((a,b) => b.score - a.score).slice(0,2).map(m => m.label);
  const worst = [...months].sort((a,b) => a.score - b.score).slice(0,2).map(m => m.label);

  const lk = LUCKY[st.yongsin];
  const lucky = {
    element: st.yongsin, ...lk,
    helper: HELPER[roles[st.yongsin]],
    role: roles[st.yongsin],
  };

  const advice = [
    ADVICE_ILGAN[saju.dayMaster.stem],
    ADVICE_LEVEL[st.level],
    `${year}년의 열쇠는 ${st.yongsin}입니다. ${YONGSIN[st.yongsin].b}`,
    rawTotal >= 62
      ? "올해는 문이 열리는 쪽입니다. 다만 열린 문이 많을수록 하나를 고르는 일이 어려워지니, 연초에 올해의 한 가지를 정해두세요."
      : rawTotal >= 45
      ? "올해는 조용한 해입니다. 조용한 해를 잘 쓴 사람이 다음 해를 가져갑니다. 눈에 보이는 성과보다 기반을 만드는 데 시간을 쓰세요."
      : "올해는 지키는 해입니다. 버티는 것도 전략이고, 아무 일 없이 한 해를 통과하는 것 자체가 성과인 시기가 있습니다.",
  ];

  return {
    year, gapja: ys + yb, gapjaCn: ysCn + ybCn, age: ageNow, ageThatYear: age,
    title: `${year}년 ${ysCn}${ybCn} 운세`,
    gwaesa: GWAESA[yb],
    lead: `천간 ${ysCn}(${RGAN_EL[ys]}·${stemSipsin}), 지지 ${ybCn}(${RJI_EL[yb]}·${branchSipsin})로 들어옵니다.`,
    daeun: dae,
    samjae,
    zodiac: saju.zodiac,
    overview: [
      `올해는 ${dae.gapjaCn} 대운(${dae.sipsin}) 안에서 맞는 ${ysCn}${ybCn}년입니다. 대운이 10년짜리 지형이라면 세운은 그 위에 부는 한 해의 바람입니다.`,
      `천간으로 들어오는 ${ysCn}은 ${RGAN_EL[ys]}이고, 당신에게는 ${stemSipsin}입니다. ${SIPSIN_TRAIT[stemSipsin]}`,
      `지지로 들어오는 ${ybCn}은 ${RJI_EL[yb]}이고, ${branchSipsin}에 해당합니다. ${SIPSIN_TRAIT[branchSipsin]}`,
      yearEls.includes(st.yongsin)
        ? `올해의 기운에 용신 ${IGA(st.yongsin)} 들어 있습니다. 부족하던 자리가 채워지는 해라 같은 노력에도 결과가 크게 나옵니다.`
        : yearEls.includes(st.gisin)
        ? `올해의 기운에 기신 ${IGA(st.gisin)} 들어 있습니다. 이미 넘치는 쪽이 더 두꺼워지는 해라 늘리기보다 덜어내는 선택이 맞습니다.`
        : "올해의 기운은 용신과도 기신과도 직접 닿지 않습니다. 외부 변수가 크지 않은 해라 본인의 선택이 결과를 거의 결정합니다.",
      `${saju.zodiac}띠인 당신에게 ${year}년은 ${samjae.on ? samjae.stage + "에 해당합니다" : "삼재가 아닙니다"}. ${samjae.text}`,
    ],
    fields, months, best, worst, lucky, advice,
    totalScore: rawTotal,
  };
}

export { FIELDS };
